// مولَّد تلقائياً من site/ بواسطة tools/build-worker.mjs — لا تعدّله يدوياً
const FILES = {"/admin.html":{"type":"text/html; charset=utf-8","text":"\u003c!DOCTYPE html>\n\u003chtml lang=\"ar\" dir=\"rtl\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\u003cmeta name=\"referrer\" content=\"no-referrer\">\n\u003cmeta name=\"robots\" content=\"noindex, nofollow\">\n\u003ctitle>الإدارة — pump.zeen\u003c/title>\n\u003clink rel=\"icon\" href=\"assets/img/favicon.svg\" type=\"image/svg+xml\">\n\u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n\u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n\u003clink rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/tokens.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/base.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/app.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/pages.css\">\n\u003c/head>\n\u003cbody>\n\u003cheader class=\"topbar\">\n  \u003ca class=\"brand\" href=\"app.html\" aria-label=\"pump.zeen\">\u003cspan data-logo>\u003c/span>pump.zeen\u003c/a>\n  \u003cspan class=\"project\">لوحة الإدارة\u003c/span>\n  \u003ca class=\"btn quiet\" href=\"app.html\">المصمم\u003c/a>\n  \u003cbutton class=\"btn quiet\" id=\"outBtn\">خروج\u003c/button>\n\u003c/header>\n\u003cmain class=\"page hidden\" id=\"admin\">\n  \u003ch1>الإدارة\u003c/h1>\n  \u003cp class=\"lead\">المستخدمون والتصاميم وسجل الدخول. هذه البيانات لا تُرسل إلا لحساب دوره «مدير»، والتحقق يتم في قاعدة البيانات.\u003c/p>\n  \u003cdiv class=\"stats\" id=\"stats\">\u003c/div>\n\n  \u003csection class=\"panel\">\u003ch2>التسجيل \u003clabel class=\"check\">\u003cinput type=\"checkbox\" id=\"signups\"> \u003cspan>السماح بحسابات جديدة\u003c/span>\u003c/label>\u003c/h2>\u003c/section>\n\n  \u003csection class=\"panel\">\u003ch2>المستخدمون\u003c/h2>\u003cdiv class=\"body scroll-x\">\u003ctable class=\"table\" id=\"users\">\u003c/table>\u003c/div>\u003c/section>\n  \u003csection class=\"panel\">\u003ch2>آخر عمليات الدخول\u003c/h2>\u003cdiv class=\"body scroll-x\">\u003ctable class=\"table\" id=\"log\">\u003c/table>\u003c/div>\u003c/section>\n  \u003csection class=\"panel\">\u003ch2>كل التصاميم\u003c/h2>\u003cdiv class=\"body scroll-x\">\u003ctable class=\"table\" id=\"designs\">\u003c/table>\u003c/div>\u003c/section>\n\u003c/main>\n\u003cp class=\"page muted\" id=\"wait\">جارٍ التحقق من الصلاحية…\u003c/p>\n\u003cscript type=\"module\" src=\"assets/js/pages/admin.js\">\u003c/script>\n\u003c/body>\n\u003c/html>\n"},"/app.html":{"type":"text/html; charset=utf-8","text":"\u003c!DOCTYPE html>\n\u003chtml lang=\"ar\" dir=\"rtl\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\u003cmeta name=\"referrer\" content=\"no-referrer\">\n\u003cmeta name=\"robots\" content=\"noindex\">\n\u003ctitle>المصمم — pump.zeen\u003c/title>\n\u003clink rel=\"icon\" href=\"assets/img/favicon.svg\" type=\"image/svg+xml\">\n\u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n\u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n\u003clink rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/tokens.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/base.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/app.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/scene.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/report.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/auth.css\">\n\u003c/head>\n\u003cbody>\n\n\u003c!-- بوابة الدخول (معاينة Claude فقط؛ على نطاقك تُستخدم صفحة index.html) -->\n\u003csection id=\"gate\" class=\"auth hidden\">\n  \u003cdiv class=\"auth-card\">\n    \u003ca class=\"brand\" href=\"#\" aria-label=\"pump.zeen\">\u003cspan data-logo>\u003c/span>pump.zeen\u003c/a>\n    \u003ch1>ادخل إلى المصمم\u003c/h1>\n    \u003cp class=\"muted\">الدخول بحسابك في Claude. تصاميمك في مساحة خاصة لا يقرؤها غيرك.\u003c/p>\n    \u003cbutton class=\"btn primary wide\" id=\"gateBtn\">تسجيل الدخول\u003c/button>\n    \u003cp id=\"gateMsg\" class=\"small muted\" role=\"status\">\u003c/p>\n  \u003c/div>\n\u003c/section>\n\n\u003cdiv id=\"app\" class=\"hidden\">\n  \u003cheader class=\"topbar\">\n    \u003ca class=\"brand\" href=\"app.html\" aria-label=\"pump.zeen\">\u003cspan data-logo>\u003c/span>pump.zeen\u003c/a>\n    \u003clabel class=\"project\">\u003cspan>المشروع\u003c/span>\u003cinput id=\"projName\" maxlength=\"60\" placeholder=\"اسم المشروع\" autocomplete=\"off\">\u003c/label>\n    \u003cbutton class=\"btn quiet\" id=\"newBtn\" data-icon=\"plus\">\u003cspan class=\"lbl\">جديد\u003c/span>\u003c/button>\n    \u003cbutton class=\"btn quiet\" id=\"savedBtn\" data-icon=\"folder\">\u003cspan class=\"lbl\">تصاميمي\u003c/span>\u003c/button>\n    \u003cbutton class=\"btn quiet\" id=\"envBtn\" data-icon=\"gear\">\u003cspan class=\"lbl\">الظروف\u003c/span>\u003c/button>\n    \u003ca class=\"btn quiet\" href=\"catalog.html\" data-icon=\"book\">\u003cspan class=\"lbl\">الكتالوج\u003c/span>\u003c/a>\n    \u003ca class=\"btn quiet hidden\" id=\"adminLink\" href=\"admin.html\" data-icon=\"shield\">\u003cspan class=\"lbl\">الإدارة\u003c/span>\u003c/a>\n    \u003cdiv class=\"user-chip\">\u003cspan>المهندس\u003c/span>\u003cb id=\"uname\">\u003c/b>\u003c/div>\n    \u003cbutton class=\"btn quiet\" id=\"outBtn\" data-icon=\"out\">\u003cspan class=\"lbl\">خروج\u003c/span>\u003c/button>\n  \u003c/header>\n\n  \u003cmain class=\"workspace\">\n    \u003cdiv>\n      \u003cdiv class=\"sheet\">\n        \u003cdiv class=\"sheet-frame\">\n          \u003csvg id=\"scene\" viewBox=\"0 0 1000 560\" role=\"img\" aria-label=\"مقطع رأسي لشبكة الضخ\">\u003c/svg>\n          \u003cdiv class=\"titleblock\">\n            \u003cdiv>\u003csmall>المشروع\u003c/small>\u003cb id=\"tbProject\">—\u003c/b>\u003c/div>\n            \u003cdiv>\u003csmall>المبنى\u003c/small>\u003cb id=\"tbBuilding\">—\u003c/b>\u003c/div>\n            \u003cdiv>\u003csmall>المضخة\u003c/small>\u003cb id=\"tbPump\">—\u003c/b>\u003c/div>\n            \u003cdiv>\u003csmall>التاريخ\u003c/small>\u003cb id=\"tbDate\" class=\"num\">—\u003c/b>\u003c/div>\n            \u003cdiv>\u003csmall>اللوحة\u003c/small>\u003cb class=\"num\">PZ-01 · غير مقياسي\u003c/b>\u003c/div>\n          \u003c/div>\n        \u003c/div>\n      \u003c/div>\n      \u003cdiv class=\"controlbar\">\n        \u003cdiv class=\"status\" role=\"status\">\u003cspan class=\"lamp\" id=\"lamp\">\u003c/span>\u003cspan id=\"statusMsg\">\u003c/span>\u003c/div>\n        \u003cbutton class=\"btn\" id=\"run\" disabled data-icon=\"play\">\u003cspan>تشغيل\u003c/span>\u003c/button>\n        \u003cbutton class=\"btn primary\" id=\"analyze\" disabled data-icon=\"doc\">\u003cspan>المذكرة الحسابية\u003c/span>\u003c/button>\n      \u003c/div>\n    \u003c/div>\n    \u003caside class=\"inspector\" id=\"inspector\" aria-label=\"الخصائص\">\u003c/aside>\n  \u003c/main>\n\u003c/div>\n\n\u003cscript type=\"module\" src=\"assets/js/pages/app.js\">\u003c/script>\n\u003c/body>\n\u003c/html>\n"},"/assets/css/app.css":{"type":"text/css; charset=utf-8","text":"/* صفحة المصمم: الشريط العلوي، اللوحة، المفتش (لوحة الخصائص) */\n.topbar {\n  position: sticky; top: 0; z-index: 20; height: var(--bar-h);\n  display: flex; align-items: center; gap: 8px; padding: 0 max(2vw, 14px);\n  background: var(--sheet); border-bottom: 1px solid var(--rule);\n}\n.topbar .brand { margin-inline-end: 18px; }\n.topbar .project { display: flex; align-items: center; gap: 8px; margin-inline-end: auto; color: var(--ink-2); font-size: var(--fs-1); }\n.topbar .project input { border: 0; border-bottom: 1px dashed var(--rule); background: transparent; font-size: var(--fs-2); color: var(--ink); width: 200px; padding: 4px 2px; }\n.topbar .project input:focus { outline: none; border-bottom-color: var(--ink); }\n.user-chip { display: flex; align-items: center; gap: 8px; font-size: var(--fs-1); color: var(--ink-2); padding-inline: 8px; border-inline-start: 1px solid var(--rule); margin-inline-start: 4px; }\n.user-chip b { color: var(--ink); font-weight: 500; max-width: 160px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n\n.workspace {\n  display: grid; grid-template-columns: minmax(0, 1fr) 340px; gap: 14px;\n  padding: 14px max(2vw, 14px) 28px; max-width: 1560px; margin: 0 auto;\n}\n\n/* اللوحة الهندسية */\n.sheet { background: var(--sheet); border: 1px solid var(--rule); border-radius: var(--radius); padding: 10px; }\n.sheet-frame { border: 1.5px solid var(--ink); position: relative; }\n.sheet-frame::after { content: \"\"; position: absolute; inset: 4px; border: .5px solid var(--rule); pointer-events: none; }\n#scene { display: block; width: 100%; height: auto; aspect-ratio: 1000 / 560; user-select: none; touch-action: manipulation; }\n\n.titleblock {\n  display: grid; grid-template-columns: 2fr 1.2fr 1.4fr 1fr 1fr; border-top: 1.5px solid var(--ink);\n  font-size: 12px;\n}\n.titleblock > div { padding: 6px 10px; border-inline-start: 1px solid var(--rule); }\n.titleblock > div:first-child { border-inline-start: 0; }\n.titleblock small { display: block; color: var(--ink-3); font-size: 11px; }\n.titleblock b { font-weight: 600; font-size: 13px; display: block; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\n\n.controlbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 10px 2px 2px; }\n.status { flex: 1 1 260px; display: flex; align-items: center; gap: 10px; font-size: var(--fs-1); min-height: 40px; }\n.lamp { width: 10px; height: 10px; border-radius: 50%; background: var(--ink-3); flex: none; box-shadow: 0 0 0 3px var(--sheet-2); }\n.lamp.ok { background: var(--ok); } .lamp.warn { background: var(--warn); } .lamp.bad { background: var(--fault); }\n\n/* المفتش */\n.inspector { background: var(--sheet); border: 1px solid var(--rule); border-radius: var(--radius); align-self: start; position: sticky; top: calc(var(--bar-h) + 14px); max-height: calc(100dvh - var(--bar-h) - 28px); overflow: auto; }\n.insp-head { padding: 16px 18px 12px; border-bottom: 1px solid var(--rule); }\n.insp-head .kicker { font-size: 12px; color: var(--ink-3); }\n.insp-head h2 { font-size: 19px; margin-top: 2px; }\n.insp-head p { font-size: var(--fs-1); color: var(--ink-2); margin-top: 4px; }\n.insp-body { padding: 16px 18px; }\n.insp-tabs { display: flex; border-bottom: 1px solid var(--rule); }\n.insp-tabs button { flex: 1; min-height: 40px; border: 0; background: none; cursor: pointer; font-size: var(--fs-1); color: var(--ink-2); border-bottom: 2px solid transparent; }\n.insp-tabs button[aria-selected=true] { color: var(--ink); border-bottom-color: var(--ink); font-weight: 600; }\n.note { font-size: var(--fs-1); color: var(--ink-2); background: var(--sheet-2); border-inline-start: 2px solid var(--rule); padding: 10px 12px; margin: 4px 0 14px; }\n.readout { display: grid; grid-template-columns: 1fr 1fr; border: 1px solid var(--rule); margin-bottom: 14px; }\n.readout div { padding: 10px 12px; border-bottom: 1px solid var(--rule-soft); }\n.readout div:nth-child(odd) { border-inline-end: 1px solid var(--rule-soft); }\n.readout small { display: block; font-size: 11px; color: var(--ink-3); }\n.readout b { font-size: 18px; font-weight: 600; }\n.readout i { font-style: normal; font-size: 12px; color: var(--ink-2); margin-inline-start: 4px; }\n.sequence { list-style: none; padding: 0; margin: 0 0 16px; counter-reset: s; }\n.sequence li { counter-increment: s; display: flex; gap: 12px; align-items: center; padding: 10px 0; border-bottom: 1px solid var(--rule-soft); font-size: var(--fs-2); color: var(--ink-3); }\n.sequence li::before { content: counter(s); width: 26px; height: 26px; flex: none; display: grid; place-items: center; border: 1px solid var(--rule); border-radius: 50%; font-size: 12px; }\n.sequence li.done { color: var(--ink-2); } .sequence li.done::before { content: \"✓\"; background: var(--ink); color: var(--sheet); border-color: var(--ink); }\n.sequence li.now { color: var(--ink); font-weight: 600; } .sequence li.now::before { border-color: var(--ink); border-width: 2px; }\n\n@media (max-width: 980px) {\n  .workspace { grid-template-columns: minmax(0, 1fr); }\n  .inspector { position: static; max-height: none; }\n}\n@media (max-width: 640px) {\n  .topbar { position: static; height: auto; flex-wrap: wrap; padding-block: 6px; }\n  .topbar .project { order: 10; width: 100%; padding-bottom: 4px; }\n  .topbar .project input { flex: 1; width: auto; }\n  .user-chip span, .user-chip { display: none; }\n  .titleblock { grid-template-columns: 1fr 1fr; }\n  .titleblock > div:nth-child(n+3) { border-top: 1px solid var(--rule); }\n  .titleblock > div:nth-child(3) { border-inline-start: 0; }\n  .topbar .btn .lbl { display: none; }\n}\n"},"/assets/css/auth.css":{"type":"text/css; charset=utf-8","text":"/* صفحة الدخول والتسجيل */\n.auth { min-height: 100dvh; display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(360px, 1fr); }\n.auth-art { background: var(--sheet); border-inline-end: 1px solid var(--rule); padding: clamp(24px, 4vw, 56px); display: flex; flex-direction: column; gap: 22px; }\n.auth-art h1 { font-size: clamp(30px, 3.4vw, 46px); line-height: 1.1; max-width: 16ch; }\n.auth-art p.lead { font-size: var(--fs-3); color: var(--ink-2); max-width: 52ch; }\n.auth-art .frame { border: 1.5px solid var(--ink); margin-top: auto; }\n.auth-art .frame svg { display: block; width: 100%; height: auto; aspect-ratio: 1000/560; }\n.facts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border-top: 1px solid var(--rule); }\n.facts div { padding: 12px 14px 0 0; font-size: var(--fs-1); color: var(--ink-2); }\n.facts b { display: block; font-size: var(--fs-2); color: var(--ink); font-weight: 600; }\n\n.auth-side { display: grid; place-items: center; padding: 28px 20px; }\n.auth-card { width: min(400px, 100%); background: var(--sheet); border: 1px solid var(--rule); border-radius: var(--radius); padding: 28px 26px; }\n#gate.auth { grid-template-columns: 1fr; place-items: center; padding: 20px; }\n.auth-card .brand { margin-bottom: 22px; }\n.auth-card h1, .auth-card h2 { font-size: var(--fs-4); margin-bottom: 6px; }\n.auth-card > p { margin-bottom: 18px; font-size: var(--fs-1); }\n.btn.wide { width: 100%; min-height: 46px; font-size: var(--fs-3); }\n.tabs { display: flex; border-bottom: 1px solid var(--rule); margin-bottom: 20px; }\n.tabs button { flex: 1; min-height: 42px; border: 0; background: none; cursor: pointer; color: var(--ink-2); border-bottom: 2px solid transparent; font-weight: 500; }\n.tabs button[aria-selected=true] { color: var(--ink); border-bottom-color: var(--ink); }\n.msg { min-height: 22px; margin-top: 12px; font-size: var(--fs-1); }\n.msg.bad { color: var(--fault); } .msg.ok { color: var(--ok); }\n.linklike { background: none; border: 0; padding: 0; color: var(--ink-2); text-decoration: underline; cursor: pointer; font-size: var(--fs-1); }\n.meter { height: 4px; background: var(--rule-soft); margin-top: 6px; }\n.meter i { display: block; height: 100%; width: 0; background: var(--fault); transition: width .2s; }\n.secure { display: flex; gap: 10px; margin-top: 22px; padding-top: 16px; border-top: 1px solid var(--rule); font-size: 12px; color: var(--ink-2); }\n.secure svg { width: 18px; height: 18px; flex: none; }\n@media (max-width: 900px) {\n  .auth { grid-template-columns: minmax(0, 1fr); }\n  .auth-art { border-inline-end: 0; border-bottom: 1px solid var(--rule); }\n  .facts { grid-template-columns: 1fr; }\n}\n"},"/assets/css/base.css":{"type":"text/css; charset=utf-8","text":"/* الأساسيات: عناصر HTML، الأزرار، الحقول، الجداول، النوافذ */\n*, *::before, *::after { box-sizing: border-box; min-width: 0; }\nhtml { -webkit-text-size-adjust: 100%; }\nhtml { overflow-x: clip; }\nbody {\n  margin: 0; background: var(--desk); color: var(--ink);\n  font: 400 var(--fs-2)/1.6 var(--font); font-variant-numeric: tabular-nums; overflow-x: clip;\n}\nh1, h2, h3, h4 { margin: 0; line-height: 1.2; font-weight: 600; text-wrap: balance; }\np { margin: 0; }\na { color: inherit; text-underline-offset: 3px; }\nbutton, input, select, textarea { font: inherit; color: inherit; }\n:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }\n.num { font-variant-numeric: tabular-nums; direction: ltr; unicode-bidi: isolate; white-space: nowrap; }\n.muted { color: var(--ink-2); }\n.small { font-size: var(--fs-1); }\n.hidden { display: none !important; }\n.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }\n\n/* أزرار */\n.btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  min-height: 40px; padding: 0 16px; border: 1px solid var(--rule); border-radius: var(--radius);\n  background: var(--sheet); color: var(--ink); font-weight: 500; font-size: var(--fs-2); cursor: pointer;\n  transition: background .15s, border-color .15s;\n}\n.btn:hover { border-color: var(--ink-2); }\n.btn:disabled { opacity: .4; cursor: not-allowed; }\n.btn.primary { background: var(--primary); border-color: var(--primary); color: var(--on-primary); }\n.btn.primary:hover { opacity: .9; }\n.btn.quiet { border-color: transparent; background: transparent; }\n.btn.quiet:hover { background: var(--sheet-2); }\n.btn.danger { color: var(--fault); }\n.btn svg { width: 18px; height: 18px; flex: none; }\n.btn.sm { min-height: 34px; padding: 0 12px; font-size: var(--fs-1); }\n@media (pointer: coarse) { .btn { min-height: 44px; } }\n\n/* حقول */\n.field { display: grid; gap: 6px; margin-bottom: 14px; }\n.field > label, .field > .lab { font-size: var(--fs-1); color: var(--ink-2); font-weight: 500; }\n.input, select.input {\n  width: 100%; min-height: 42px; padding: 0 12px; font-size: 16px;\n  border: 1px solid var(--rule); border-radius: var(--radius); background: var(--sheet);\n}\n.input:focus { border-color: var(--ink); outline: none; box-shadow: 0 0 0 3px var(--rule-soft); }\n.range-row { display: grid; grid-template-columns: minmax(0, 1fr) 92px; gap: 10px; align-items: center; }\n.range-row input[type=range] { width: 100%; accent-color: var(--ink); height: 28px; }\n.unit-box { position: relative; }\n.unit-box .input { direction: ltr; text-align: right; padding: 0 10px 0 30px; min-height: 36px; font-size: 15px; }\n.unit-box span { position: absolute; left: 8px; top: 50%; transform: translateY(-50%); font-size: 12px; color: var(--ink-3); pointer-events: none; }\n.seg { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; border: 1px solid var(--rule); border-radius: var(--radius); overflow: hidden; }\n.seg button { min-height: 38px; border: 0; background: var(--sheet); cursor: pointer; font-size: var(--fs-1); font-weight: 500; }\n.seg button + button { border-inline-start: 1px solid var(--rule); }\n.seg button[aria-pressed=true] { background: var(--primary); color: var(--on-primary); }\n.check { display: flex; gap: 10px; align-items: center; font-size: var(--fs-1); min-height: 40px; cursor: pointer; }\n.check input { width: 18px; height: 18px; accent-color: var(--ink); }\n\n/* شارات الحالة */\n.tag { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; font-weight: 600; padding: 2px 8px; border-radius: 2px; white-space: nowrap; }\n.tag::before { content: \"\"; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }\n.tag.ok { color: var(--ok); background: var(--ok-bg); }\n.tag.warn { color: var(--warn); background: var(--warn-bg); }\n.tag.bad { color: var(--fault); background: var(--fault-bg); }\n.tag.info { color: var(--ink-2); background: var(--sheet-2); }\n\n/* جداول */\n.table { width: 100%; border-collapse: collapse; font-size: var(--fs-1); }\n.table th { text-align: start; font-weight: 600; color: var(--ink-2); border-bottom: 1px solid var(--ink); padding: 8px 10px; white-space: nowrap; }\n.table td { border-bottom: 1px solid var(--rule-soft); padding: 9px 10px; vertical-align: top; }\n.table td.n, .table th.n { text-align: end; direction: ltr; }\n.scroll-x { overflow-x: auto; }\n\n/* نافذة */\n.overlay { position: fixed; inset: 0; z-index: 40; background: color-mix(in srgb, var(--desk) 70%, transparent); backdrop-filter: blur(2px); display: grid; place-items: center; padding: 16px; }\n.dialog { width: min(920px, 100%); max-height: calc(100dvh - 32px); overflow: auto; background: var(--sheet); border: 1px solid var(--ink); border-radius: var(--radius); box-shadow: 0 30px 80px -30px #0006; }\n.dialog-head { position: sticky; top: 0; z-index: 1; display: flex; gap: 12px; align-items: flex-start; justify-content: space-between; padding: 18px 22px 14px; background: var(--sheet); border-bottom: 1px solid var(--rule); }\n.dialog-head h2 { font-size: var(--fs-4); }\n.dialog-head p { color: var(--ink-2); font-size: var(--fs-1); margin-top: 4px; }\n.dialog-body { padding: 18px 22px 22px; }\n.x-btn { width: 40px; height: 40px; flex: none; border: 1px solid var(--rule); border-radius: var(--radius); background: var(--sheet); cursor: pointer; font-size: 20px; line-height: 1; }\n\n#toast { position: fixed; bottom: 18px; left: 50%; transform: translateX(-50%); z-index: 60; background: var(--primary); color: var(--on-primary); padding: 10px 16px; border-radius: var(--radius); font-size: var(--fs-1); max-width: 90vw; }\n\n/* الشعار */\n.brand { display: inline-flex; align-items: center; gap: 10px; font-weight: 700; font-size: 18px; letter-spacing: -.01em; direction: ltr; text-decoration: none; }\n.brand svg { width: 28px; height: 28px; }\n"},"/assets/css/pages.css":{"type":"text/css; charset=utf-8","text":"/* صفحات المحتوى: الكتالوج ولوحة الإدارة */\n.page { max-width: 1100px; margin: 0 auto; padding: 32px max(3vw, 16px) 60px; }\n.page > h1 { font-size: var(--fs-5); line-height: 1.1; }\n.page > .lead { font-size: var(--fs-3); color: var(--ink-2); max-width: 70ch; margin: 10px 0 20px; }\n.callout { background: var(--sheet); border: 1px solid var(--rule); border-inline-start: 3px solid var(--ink); padding: 14px 16px; margin-bottom: 18px; }\n.callout p { color: var(--ink-2); font-size: var(--fs-1); margin-top: 4px; }\n.toc { display: flex; gap: 6px; position: sticky; top: var(--bar-h); background: var(--desk); padding: 10px 0; z-index: 2; }\n.toc a { flex: none; padding: 6px 12px; border: 1px solid var(--rule); background: var(--sheet); text-decoration: none; font-size: var(--fs-1); border-radius: var(--radius); }\n.cat-sec { margin-top: 28px; }\n.cat-sec > h2 { font-size: var(--fs-4); padding-bottom: 8px; border-bottom: 1.5px solid var(--ink); }\n.cat-sec > p { margin: 8px 0 12px; }\n.src { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px 18px; background: var(--sheet); border: 1px solid var(--rule); padding: 14px 16px; margin-bottom: 14px; }\n.src small { display: block; font-size: 11px; color: var(--ink-3); }\n.src a { font-weight: 500; overflow-wrap: anywhere; }\n.src p { grid-column: 1 / -1; }\n.pump-card { background: var(--sheet); border: 1px solid var(--rule); padding: 14px 16px; margin-bottom: 10px; scroll-margin-top: 120px; }\n.pump-card header { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 12px; align-items: center; margin-bottom: 8px; }\n.pump-card header > div { flex: 1 1 220px; }\n.pump-card .spark { flex: none; }\n.pump-card h3 { font-size: var(--fs-3); direction: ltr; text-align: right; }\n.pump-card .spark svg { width: 120px; height: 40px; }\n.pump-card:target { border-color: var(--ink); box-shadow: 0 0 0 2px var(--water-bg); }\n\n/* الإدارة */\n.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); border-top: 1px solid var(--rule); border-inline-start: 1px solid var(--rule); background: var(--sheet); margin: 18px 0 8px; }\n.stats div { padding: 14px 16px; border-bottom: 1px solid var(--rule); border-inline-end: 1px solid var(--rule); }\n.stats small { display: block; color: var(--ink-2); font-size: 12px; }\n.stats b { font-size: 28px; font-weight: 600; }\n.panel { background: var(--sheet); border: 1px solid var(--rule); margin-top: 18px; }\n.panel > h2 { font-size: var(--fs-3); padding: 12px 16px; border-bottom: 1px solid var(--rule); display: flex; justify-content: space-between; align-items: center; gap: 10px; }\n.panel > .body { padding: 6px 8px 10px; }\n@media (max-width: 700px) { .src { grid-template-columns: 1fr; } }\n"},"/assets/css/report.css":{"type":"text/css; charset=utf-8","text":"/* المذكرة الحسابية (التحليل) واختيار المضخة والكتالوج */\n.verdict { display: grid; grid-template-columns: auto 1fr; gap: 4px 14px; align-items: center; padding: 14px 16px; border: 1px solid; border-radius: var(--radius); margin-bottom: 18px; }\n.verdict .lamp { grid-row: span 2; width: 14px; height: 14px; }\n.verdict b { font-size: 19px; }\n.verdict p { font-size: var(--fs-1); color: var(--ink-2); }\n.verdict.ok { border-color: var(--ok); background: var(--ok-bg); } .verdict.warn { border-color: var(--warn); background: var(--warn-bg); } .verdict.bad { border-color: var(--fault); background: var(--fault-bg); }\n\n.memo-sec { margin-top: 22px; }\n.memo-sec > h3 { display: flex; gap: 10px; align-items: baseline; font-size: var(--fs-3); padding-bottom: 8px; border-bottom: 1.5px solid var(--ink); margin-bottom: 12px; }\n.memo-sec > h3 span { font-size: var(--fs-1); color: var(--ink-3); font-weight: 500; }\n\n.kpi-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); border-top: 1px solid var(--rule); border-inline-start: 1px solid var(--rule); }\n.kpi-grid > div { padding: 12px 14px; border-bottom: 1px solid var(--rule); border-inline-end: 1px solid var(--rule); }\n.kpi-grid small { display: block; font-size: 12px; color: var(--ink-2); }\n.kpi-grid b { font-size: 22px; font-weight: 600; }\n.kpi-grid i { font-style: normal; font-size: 12px; color: var(--ink-3); margin-inline-start: 4px; }\n\n.chart { border: 1px solid var(--rule); padding: 10px; }\n.chart svg { display: block; width: 100%; height: auto; }\n.chart .legend { display: flex; flex-wrap: wrap; gap: 6px 18px; font-size: 12px; color: var(--ink-2); padding: 8px 4px 0; }\n.chart .legend span { display: inline-flex; align-items: center; gap: 6px; }\n.chart .legend i { width: 18px; height: 0; border-top: 2px solid var(--c); display: inline-block; }\n.chart .legend i.dash { border-top-style: dashed; }\n\n.checks td:first-child { width: 120px; }\n.checks .fixes { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }\n.checks td p { color: var(--ink-2); margin-top: 2px; }\n\n.pump-table tr.rec td:first-child b::after { content: \"موصى بها\"; margin-inline-start: 8px; font-size: 11px; font-weight: 600; padding: 1px 6px; background: var(--primary); color: var(--on-primary); border-radius: 2px; }\n.pump-table tr { cursor: pointer; }\n.pump-table tr:hover td { background: var(--sheet-2); }\n.pump-table tr.cur td { background: var(--water-bg); }\n.pump-table svg { width: 90px; height: 32px; display: block; }\n.source-line { margin-top: 14px; font-size: 12px; color: var(--ink-2); }\n.source-line a { color: var(--ink); }\n\n@media (max-width: 640px) {\n  .pump-table .opt { display: none; }\n  .checks td:first-child { width: auto; }\n  .dialog-body, .dialog-head { padding-inline: 14px; }\n}\n@media print {\n  body > *:not(.overlay) { display: none !important; }\n  .overlay { position: static; background: none; backdrop-filter: none; padding: 0; }\n  .dialog { border: 0; box-shadow: none; max-height: none; width: 100%; }\n  .dialog-head .x-btn, .no-print, .fixes { display: none !important; }\n}\n"},"/assets/css/scene.css":{"type":"text/css; charset=utf-8","text":"/* عناصر الرسم داخل المشهد (SVG) */\n#scene { --line: var(--ink); }\n.s-ground { stroke: var(--ink); stroke-width: 2; }\n.s-thin { stroke: var(--ink); stroke-width: 1; fill: none; }\n.s-hair { stroke: var(--rule); stroke-width: .75; fill: none; }\n.s-fill { fill: var(--sheet); stroke: var(--ink); stroke-width: 1.25; }\n.s-slab { fill: var(--ink); }\n.s-win { fill: var(--sheet-2); stroke: var(--ink-2); stroke-width: .75; }\n.s-water { fill: var(--water-bg); }\n.s-wline { stroke: var(--water); stroke-width: 1.5; fill: none; }\n.s-txt { fill: var(--ink); font: 500 12px var(--font); }\n.s-txt.mute { fill: var(--ink-2); font-weight: 400; }\n.s-txt.big { font-size: 14px; font-weight: 600; }\n.s-num { direction: ltr; unicode-bidi: isolate; }\n.s-dim { stroke: var(--ink-2); stroke-width: .75; fill: none; }\n.s-arrow { fill: var(--ink-2); }\n.s-tagbg { fill: var(--sheet); }\n\n.pipe-wall { fill: none; stroke: var(--ink); stroke-linecap: butt; stroke-linejoin: round; }\n.pipe-core { fill: none; stroke-linecap: butt; stroke-linejoin: round; }\n.pipe-core.pvc { stroke: var(--sheet); } .pipe-core.steel { stroke: var(--ink-2); } .pipe-core.galv { stroke: var(--hatch); } .pipe-core.cast { stroke: var(--ink-3); }\n.pipe-flow { fill: none; stroke: var(--water); stroke-linecap: round; stroke-dasharray: 8 10; animation: flow .8s linear infinite; }\n@keyframes flow { to { stroke-dashoffset: -18; } }\n.pipe-hit { fill: none; stroke: transparent; stroke-width: 24; cursor: pointer; pointer-events: stroke; }\n.is-sel .pipe-wall { stroke: var(--water); }\n\n.hot { cursor: pointer; outline: none; }\n.hot:hover .s-fill, .hot:focus-visible .s-fill { stroke: var(--water); }\n.hot.is-sel .s-fill { stroke: var(--water); stroke-width: 2; }\n\n.slot { cursor: pointer; outline: none; }\n.slot { pointer-events: all; }\n.slot rect { fill: transparent; stroke: var(--ink-2); stroke-width: 1.2; stroke-dasharray: 6 5; }\n.slot text { fill: var(--ink-2); font: 500 13px var(--font); }\n.slot .plus { stroke: var(--ink-2); stroke-width: 1.5; }\n.slot:hover rect, .slot:focus-visible rect { stroke: var(--ink); stroke-dasharray: none; }\n.slot:hover text, .slot:focus-visible text { fill: var(--ink); }\n.slot.next rect { stroke: var(--ink); stroke-width: 1.5; }\n.slot.next text { fill: var(--ink); font-weight: 600; }\n\n.fx-drop { fill: var(--water); animation: drop 1s ease-in infinite; }\n@keyframes drop { from { transform: translateY(0); opacity: 1; } to { transform: translateY(44px); opacity: 0; } }\n.fx-bub { fill: var(--sheet); stroke: var(--water); stroke-width: 1; animation: bub 1.2s ease-out infinite; }\n@keyframes bub { from { transform: translateY(0); opacity: 1; } to { transform: translateY(-22px); opacity: 0; } }\n.fx-shake { animation: shake .12s linear infinite; }\n@keyframes shake { 50% { transform: translate(1.2px, -.8px); } }\n.fx-spin { animation: spin .6s linear infinite; transform-box: fill-box; transform-origin: center; }\n@keyframes spin { to { transform: rotate(360deg); } }\n@media (prefers-reduced-motion: reduce) { .pipe-flow, .fx-drop, .fx-bub, .fx-shake, .fx-spin { animation: none; } }\n"},"/assets/css/tokens.css":{"type":"text/css; charset=utf-8","text":"/* ═══════════════════════════════════════════════════════════════\n   الألوان والخطوط والمقاسات — غيّر الهوية من هنا فقط\n   الفكرة: لوحة رسم هندسي. فاتح = ورق أبيض وحبر، داكن = مخطط أزرق (Blueprint)\n   ═══════════════════════════════════════════════════════════════ */\n:root {\n  color-scheme: light dark;\n  --desk:      light-dark(#e6eaee, #06182b);\n  --sheet:     light-dark(#ffffff, #0b2440);\n  --sheet-2:   light-dark(#f5f7f9, #0e2b4b);\n  --ink:       light-dark(#101b25, #dceaf8);\n  --ink-2:     light-dark(#4a5b69, #93b3d1);\n  --ink-3:     light-dark(#7d8c98, #6f92b4);\n  --rule:      light-dark(#c3cdd5, #2b5279);\n  --rule-soft: light-dark(#e1e7ec, #163a5f);\n  --hatch:     light-dark(#b9c4cd, #2a537c);\n  --water:     light-dark(#1b74c9, #63bdff);\n  --water-bg:  light-dark(#d6e9fa, #123e66);\n  --primary:   light-dark(#101b25, #dceaf8);\n  --on-primary:light-dark(#ffffff, #06182b);\n  --ok:        light-dark(#25734a, #62d39c);\n  --warn:      light-dark(#9a5b00, #f0bf55);\n  --fault:     light-dark(#c03a0c, #ff8d57);\n  --ok-bg:     light-dark(#e6f2eb, #0f3b33);\n  --warn-bg:   light-dark(#fbf1df, #3a3218);\n  --fault-bg:  light-dark(#fbe9e1, #43231b);\n  --focus:     light-dark(#1b74c9, #63bdff);\n\n  --font: \"IBM Plex Sans Arabic\", \"Segoe UI\", Tahoma, sans-serif;\n  --fs-1: 13px; --fs-2: 15px; --fs-3: 17px; --fs-4: 22px; --fs-5: 34px;\n  --radius: 3px;\n  --gap: 16px;\n  --bar-h: 56px;\n}\n:root[data-theme=light] { color-scheme: light; }\n:root[data-theme=dark]  { color-scheme: dark; }\n"},"/assets/img/favicon.svg":{"type":"image/svg+xml","text":"\u003csvg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\">\u003crect width=\"32\" height=\"32\" rx=\"6\" fill=\"#101b25\"/>\u003cg transform=\"translate(3 3) scale(.8125)\" stroke=\"#fff\" fill=\"none\" stroke-width=\"2.4\">\u003cpath d=\"M16 3a13 13 0 1 0 13 13h-4a9 9 0 1 1-9-9z\"/>\u003cpath d=\"M25 16h4V3h-4\" stroke-linejoin=\"round\"/>\u003c/g>\u003cg fill=\"#fff\" transform=\"translate(3 3) scale(.8125)\">\u003cpath d=\"M16 16c0-3 1.4-5 3.6-5.6-.4 2.4-1.6 4.3-3.6 5.6z\"/>\u003cpath transform=\"rotate(120 16 16)\" d=\"M16 16c0-3 1.4-5 3.6-5.6-.4 2.4-1.6 4.3-3.6 5.6z\"/>\u003cpath transform=\"rotate(240 16 16)\" d=\"M16 16c0-3 1.4-5 3.6-5.6-.4 2.4-1.6 4.3-3.6 5.6z\"/>\u003ccircle cx=\"16\" cy=\"16\" r=\"1.8\"/>\u003c/g>\u003c/svg>\n"},"/assets/js/auth/claude.js":{"type":"text/javascript; charset=utf-8","text":"// مزوّد المعاينة داخل Claude: الهوية من حساب Claude، والحفظ في مساحة خاصة لكل مستخدم\nlet user = null, db = null;\n\nexport const claudeAuth = {\n  name: 'claude',\n  configured: () => !!(window.claude && typeof window.claude.use === 'function'),\n  async init() { return user; },\n  user: () => user,\n  async signIn() {\n    const u = await window.claude.use('user');\n    if (!u) throw new Error('تعذّر التحقق من الهوية. افتح الصفحة من claude.ai وأنت مسجّل الدخول.');\n    const id = await u.id();\n    if (!id || typeof id !== 'string') throw new Error('تعذّر التحقق من الهوية.');\n    const me = await u.me();\n    user = { id, email: '', name: (me && me.name) || 'مهندس' };\n    db = await window.claude.use('db');\n    return user;\n  },\n  async signOut() { user = null; db = null; },\n  async isAdmin() { return false; },\n  db: () => db,\n};\n"},"/assets/js/auth/index.js":{"type":"text/javascript; charset=utf-8","text":"// اختيار مزوّد الدخول ومراقبة الخمول — واجهة واحدة لكل الصفحات\nimport { CONFIG } from '../config.js';\nimport { supabaseAuth } from './supabase.js';\nimport { claudeAuth } from './claude.js';\n\nfunction pick() {\n  if (CONFIG.authProvider === 'supabase') return supabaseAuth;\n  if (CONFIG.authProvider === 'claude') return claudeAuth;\n  return claudeAuth.configured() ? claudeAuth : supabaseAuth;\n}\nexport const auth = pick();\n\n// إغلاق الجلسة بعد مدة خمول\nexport function watchIdle(onTimeout) {\n  let t;\n  const reset = () => { clearTimeout(t); t = setTimeout(onTimeout, CONFIG.idleMinutes * 60e3); };\n  ['pointerdown', 'keydown', 'pointermove', 'touchstart', 'scroll'].forEach(e => addEventListener(e, reset, { passive: true }));\n  reset();\n  return () => clearTimeout(t);\n}\n\n// صفحات محمية: إن لم توجد جلسة → صفحة الدخول\nexport async function requireUser() {\n  if (auth.name === 'claude') return auth.user();\n  const u = await auth.init();\n  if (!u) { location.replace('index.html'); return null; }\n  return u;\n}\n"},"/assets/js/auth/supabase.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// عميل Supabase مصغّر بدون مكتبات خارجية (Auth + REST + RPC)\n// • رمز الدخول (access token) في الذاكرة فقط\n// • رمز التجديد في sessionStorage — يُمسح بإغلاق التبويب\n// • كل صلاحية حقيقية تُفرض في قاعدة البيانات عبر RLS، لا في المتصفح\n// ═══════════════════════════════════════════════════════════════\nimport { CONFIG } from '../config.js';\n\nconst RT_KEY = 'pz.rt';\nlet session = null; // { access, exp, user }\nlet refreshTimer = null;\n\nconst base = () => CONFIG.supabaseUrl.replace(/\\/+$/, '');\nconst headers = (auth = true) => {\n  const h = { apikey: CONFIG.supabaseKey, 'Content-Type': 'application/json' };\n  if (auth && session) h.Authorization = 'Bearer ' + session.access;\n  return h;\n};\nconst store = {\n  get: () => { try { return sessionStorage.getItem(RT_KEY); } catch { return null; } },\n  set: v => { try { v ? sessionStorage.setItem(RT_KEY, v) : sessionStorage.removeItem(RT_KEY); } catch {} },\n};\n\n// رسائل الأخطاء بالعربية دون كشف تفاصيل داخلية\nfunction friendly(status, body) {\n  const m = String(body?.error_code || body?.msg || body?.message || body?.error_description || '').toLowerCase();\n  if (m.includes('invalid') && m.includes('credential') || m.includes('invalid_grant') || m.includes('invalid login')) return 'البريد أو كلمة المرور غير صحيحة.';\n  if (m.includes('email_not_confirmed') || m.includes('not confirmed')) return 'فعّل حسابك من الرابط المرسل إلى بريدك أولاً.';\n  if (m.includes('already') && m.includes('registered') || m.includes('user_already_exists')) return 'هذا البريد مسجّل مسبقاً.';\n  if (m.includes('weak') || m.includes('password should')) return 'كلمة المرور ضعيفة: 10 أحرف على الأقل وتشمل حروفاً وأرقاماً.';\n  if (status === 429 || m.includes('rate')) return 'محاولات كثيرة. انتظر قليلاً ثم أعد المحاولة.';\n  if (m.includes('database error saving new user') || m.includes('signups')) return 'التسجيل مغلق حالياً.';\n  return 'تعذّر إكمال الطلب. حاول مرة أخرى.';\n}\n\nasync function call(path, { method = 'GET', body, auth = true, prefer } = {}) {\n  const h = headers(auth);\n  if (prefer) h.Prefer = prefer;\n  let res;\n  try {\n    res = await fetch(base() + path, { method, headers: h, body: body ? JSON.stringify(body) : undefined, credentials: 'omit', cache: 'no-store' });\n  } catch { throw new Error('لا يوجد اتصال بالخادم.'); }\n  const txt = await res.text();\n  let data = null; try { data = txt ? JSON.parse(txt) : null; } catch {}\n  if (!res.ok) { const e = new Error(friendly(res.status, data)); e.status = res.status; throw e; }\n  return data;\n}\n\nfunction accept(tok) {\n  if (!tok?.access_token) return null;\n  const u = tok.user || {};\n  session = {\n    access: tok.access_token,\n    exp: Date.now() + (tok.expires_in || 3600) * 1000,\n    user: { id: u.id, email: u.email, name: u.user_metadata?.full_name || (u.email || '').split('@')[0] },\n  };\n  store.set(tok.refresh_token);\n  clearTimeout(refreshTimer);\n  refreshTimer = setTimeout(() => refresh().catch(() => {}), Math.max(30e3, (tok.expires_in || 3600) * 1000 - 120e3));\n  return session.user;\n}\n\nasync function refresh() {\n  const rt = store.get();\n  if (!rt) return null;\n  try { return accept(await call('/auth/v1/token?grant_type=refresh_token', { method: 'POST', auth: false, body: { refresh_token: rt } })); }\n  catch { store.set(null); session = null; return null; }\n}\n\nexport const supabaseAuth = {\n  name: 'supabase',\n  configured: () => !!(CONFIG.supabaseUrl && CONFIG.supabaseKey),\n  async init() { return session?.user || refresh(); },\n  user: () => session?.user || null,\n  async signIn(email, password) {\n    return accept(await call('/auth/v1/token?grant_type=password', { method: 'POST', auth: false, body: { email, password } }));\n  },\n  async signUp(email, password, fullName) {\n    const r = await call('/auth/v1/signup', { method: 'POST', auth: false, body: { email, password, data: { full_name: fullName } } });\n    return r?.access_token ? { user: accept(r), confirm: false } : { user: null, confirm: true };\n  },\n  async resetPassword(email) {\n    await call('/auth/v1/recover?redirect_to=' + encodeURIComponent(location.origin + '/reset.html'), { method: 'POST', auth: false, body: { email } });\n  },\n  async signOut() {\n    try { if (session) await call('/auth/v1/logout', { method: 'POST' }); } catch {}\n    clearTimeout(refreshTimer); session = null; store.set(null);\n  },\n  // من رابط «نسيت كلمة المرور»: الرمز يصل في عنوان الصفحة بعد #\n  async setPasswordWithToken(token, password) {\n    const r = await fetch(base() + '/auth/v1/user', { method: 'PUT', credentials: 'omit', cache: 'no-store',\n      headers: { apikey: CONFIG.supabaseKey, 'Content-Type': 'application/json', Authorization: 'Bearer ' + token }, body: JSON.stringify({ password }) });\n    if (!r.ok) { let b = null; try { b = await r.json(); } catch {} throw new Error(friendly(r.status, b)); }\n  },\n  async isAdmin() { try { return (await call('/rest/v1/rpc/is_admin', { method: 'POST', body: {} })) === true; } catch { return false; } },\n  rpc: (fn, args = {}) => call('/rest/v1/rpc/' + encodeURIComponent(fn), { method: 'POST', body: args }),\n  rest: call,\n};\n"},"/assets/js/config.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// إعدادات الموقع — الملف الوحيد الذي تحتاج تعديله عند النشر\n// ═══════════════════════════════════════════════════════════════\nexport const CONFIG = {\n  siteName: 'pump.zeen',\n\n  // مزوّد تسجيل الدخول:\n  //  'auto'     → Supabase على نطاقك، وحساب Claude داخل معاينة Claude\n  //  'supabase' → دائماً Supabase\n  //  'claude'   → دائماً حساب Claude (المعاينة فقط)\n  authProvider: 'auto',\n\n  // من لوحة Supabase: Project Settings → API\n  // (المفتاح العام publishable/anon آمن للنشر؛ لا تضع هنا service_role أبداً)\n  supabaseUrl: 'https://rmuwprafvgqwemohrcce.supabase.co',\n  supabaseKey: 'sb_publishable_RngE_JXMnTFeSDhN_TwhWg_Ef0ge03k',\n\n  // إغلاق الجلسة تلقائياً بعد عدم النشاط (بالدقائق)\n  idleMinutes: 20,\n\n  // قيم افتراضية للتصميم\n  defaults: {\n    waterTempC: 30,\n    altitudeM: 600,          // الرياض تقريباً\n    pumpingHours: 4,\n    tariffSarPerKwh: 0.18,   // تعرفة سكنية تقريبية؛ عدّلها حسب شريحتك\n    gridHz: 60,              // شبكة الكهرباء في السعودية\n  },\n};\n"},"/assets/js/core/dom.js":{"type":"text/javascript; charset=utf-8","text":"// أدوات DOM صغيرة — كل نص قادم من المستخدم أو الخادم يمر عبر esc أو textContent\nexport const $ = (s, r = document) => r.querySelector(s);\nexport const $$ = (s, r = document) => [...r.querySelectorAll(s)];\nexport const esc = v => String(v).replace(/[&\u003c>\"']/g, c => ({ '&': '&amp;', '\u003c': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nexport function el(tag, attrs = {}, ...kids) {\n  const e = document.createElement(tag);\n  for (const [k, v] of Object.entries(attrs)) {\n    if (k === 'class') e.className = v;\n    else if (k === 'text') e.textContent = v;\n    else if (k.startsWith('on')) e.addEventListener(k.slice(2), v);\n    else if (v !== false && v != null) e.setAttribute(k, v === true ? '' : v);\n  }\n  for (const k of kids) if (k != null) e.append(k);\n  return e;\n}\nexport const reduceMotion = () => matchMedia('(prefers-reduced-motion: reduce)').matches;\n"},"/assets/js/core/format.js":{"type":"text/javascript; charset=utf-8","text":"// تنسيق الأرقام — أرقام لاتينية كما في المخططات الهندسية\nconst f = d => new Intl.NumberFormat('en-US', { maximumFractionDigits: d, minimumFractionDigits: 0 });\nconst F0 = f(0), F1 = f(1), F2 = f(2);\nconst safe = (fmt, v) => Number.isFinite(v) ? fmt.format(v) : '—';\nexport const n0 = v => safe(F0, v);\nexport const n1 = v => safe(F1, v);\nexport const n2 = v => safe(F2, v);\nexport const pct = v => safe(F0, v * 100) + '%';\nexport const date = t => new Date(t).toLocaleDateString('ar-SA-u-nu-latn', { year: 'numeric', month: 'short', day: 'numeric' });\n"},"/assets/js/core/sanitize.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// التحقق من أي تصميم قادم من التخزين أو الخادم قبل استخدامه\n// لا يُقبل إلا الحقول المعروفة، وكل رقم يُحصر في حدوده\n// ═══════════════════════════════════════════════════════════════\nimport { fresh } from './store.js';\nimport { BUILDINGS } from '../data/buildings.js';\nimport { MATERIALS, DIAMETERS } from '../data/materials.js';\nimport { PUMPS } from '../data/pumps.js';\n\nexport const LIMITS = {\n  'building.floors': [1, 20, 1], 'building.floorH': [2.6, 6, 0.1], 'building.perFloor': [1, 400, 1],\n  'ground.vol': [1, 400, 1], 'ground.depth': [0.5, 4, 0.1], 'roof.vol': [0.5, 60, 0.5],\n  'site': [3, 40, 0.5], 'pump.x': [0.5, 39.5, 0.5], 'pump.z': [0, 3, 0.1],\n  'suction.L': [0.5, 80, 0.5], 'discharge.L': [1, 300, 0.5], 'suction.elbows': [0, 10, 1], 'discharge.elbows': [0, 20, 1], 'discharge.valveK': [0, 400, 0.5],\n  'env.waterTempC': [1, 90, 1], 'env.altitudeM': [0, 3000, 50], 'env.pumpingHours': [1, 24, 1], 'env.tariff': [0, 2, 0.01],\n};\n\nexport const num = (v, [a, b], d) => { v = Number(v); return Number.isFinite(v) ? Math.min(b, Math.max(a, v)) : d; };\nconst pick = (v, list, d) => (list.includes(v) ? v : d);\nconst text = (v, max) => String(v ?? '').replace(/[\\u0000-\\u001f\u003c>]/g, '').trim().slice(0, max);\n\nexport function cleanDesign(o) {\n  const s = fresh();\n  if (!o || typeof o !== 'object') return s;\n  s.name = text(o.name, 60);\n  s.site = num(o.site, LIMITS.site, 10);\n  s.autoLength = o.autoLength !== false;\n  if (o.env) s.env = {\n    waterTempC: num(o.env.waterTempC, LIMITS['env.waterTempC'], s.env.waterTempC),\n    altitudeM: num(o.env.altitudeM, LIMITS['env.altitudeM'], s.env.altitudeM),\n    pumpingHours: num(o.env.pumpingHours, LIMITS['env.pumpingHours'], s.env.pumpingHours),\n    tariff: num(o.env.tariff, LIMITS['env.tariff'], s.env.tariff),\n  };\n  const b = o.building;\n  if (b) {\n    const type = pick(b.type, Object.keys(BUILDINGS), 'house'), T = BUILDINGS[type];\n    s.building = { type, floors: Math.round(num(b.floors, LIMITS['building.floors'], T.floors)),\n      floorH: num(b.floorH, LIMITS['building.floorH'], T.floorH), perFloor: Math.round(num(b.perFloor, LIMITS['building.perFloor'], T.perFloor)) };\n  }\n  if (s.building && o.roof) s.roof = { vol: num(o.roof.vol, LIMITS['roof.vol'], 2) };\n  if (s.building && o.ground) s.ground = { vol: num(o.ground.vol, LIMITS['ground.vol'], 4), depth: num(o.ground.depth, LIMITS['ground.depth'], 1.5) };\n  if (s.roof && s.ground && o.pump && o.suction && o.discharge) {\n    s.pump = { id: pick(o.pump.id, PUMPS.map(p => p.id), PUMPS[0].id),\n      x: num(o.pump.x, [0.5, s.site - 0.5], 3), z: num(o.pump.z, LIMITS['pump.z'], 0.3) };\n    const pipe = (p, k) => ({ L: num(p.L, LIMITS[k + '.L'], 5), d: pick(Number(p.d), DIAMETERS, 32),\n      mat: pick(p.mat, Object.keys(MATERIALS), 'pvc'), elbows: Math.round(num(p.elbows, LIMITS[k + '.elbows'], 2)) });\n    s.suction = pipe(o.suction, 'suction'); s.discharge = pipe(o.discharge, 'discharge');\n    s.discharge.valveK = num(o.discharge.valveK, LIMITS['discharge.valveK'], 0);\n  }\n  return s;\n}\n"},"/assets/js/core/store.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// حالة التصميم — مصدر واحد للحقيقة\n// كل تعديل يمر عبر update() فيُعاد رسم الواجهات المشتركة تلقائياً\n// ═══════════════════════════════════════════════════════════════\nimport { CONFIG } from '../config.js';\n\nexport const fresh = () => ({\n  name: '',\n  building: null,       // { type, floors, floorH, perFloor }\n  roof: null,           // { vol }\n  ground: null,         // { vol, depth }\n  pump: null,           // { id, x, z }\n  suction: null,        // { L, d, mat, elbows }\n  discharge: null,\n  site: 10,             // المسافة بين الخزان الأرضي والمبنى (م)\n  autoLength: true,\n  env: {\n    waterTempC: CONFIG.defaults.waterTempC,\n    altitudeM: CONFIG.defaults.altitudeM,\n    pumpingHours: CONFIG.defaults.pumpingHours,\n    tariff: CONFIG.defaults.tariffSarPerKwh,\n  },\n});\n\nlet state = fresh();\nconst ui = { selected: null, running: false, fill: 0.15 };\nconst subs = new Set();\n\nexport const getState = () => state;\nexport const getUI = () => ui;\nexport const subscribe = fn => (subs.add(fn), () => subs.delete(fn));\nconst emit = why => subs.forEach(fn => fn(state, ui, why));\n\nexport function update(mutator, why = 'state') { mutator(state); emit(why); }\nexport function setUI(patch, why = 'ui') { Object.assign(ui, patch); emit(why); }\nexport function replace(next, why = 'load') { state = next; ui.selected = null; ui.running = false; ui.fill = 0.15; emit(why); }\nexport const isComplete = s => !!(s.building && s.roof && s.ground && s.pump && s.suction);\n"},"/assets/js/data/buildings.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// أنواع المباني ومعدلات الاستهلاك\n// rate: لتر/شخص/يوم — قيم تصميمية شائعة، عدّلها حسب كود البلدية أو المشروع\n// ═══════════════════════════════════════════════════════════════\nexport const BUILDINGS = {\n  house:   { name: 'بيت',    rate: 200, perFloor: 5,   floors: 2, floorH: 3.2, people: 'السكان',  desc: 'سكني — 200 لتر للفرد يومياً' },\n  school:  { name: 'مدرسة',  rate: 45,  perFloor: 120, floors: 3, floorH: 3.6, people: 'الطلاب',  desc: 'تعليمي — 45 لتر للطالب يومياً' },\n  factory: { name: 'مصنع',   rate: 120, perFloor: 30,  floors: 2, floorH: 5.0, people: 'العمال',  desc: 'صناعي خفيف — 120 لتر للعامل يومياً' },\n};\n\n// نسب سعة الخزانات من الاستهلاك اليومي\nexport const TANK_RULES = {\n  roofShare: 0.5,     // العلوي = نصف يوم\n  groundShare: 1.0,   // الأرضي = يوم كامل\n  roofMin: 1, groundMin: 2,\n  roofInletAboveRoof: 1.2, // ارتفاع مدخل الخزان العلوي فوق السطح (م)\n};\n"},"/assets/js/data/materials.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// مواد المواسير والأقطار والقطع\n// e: الخشونة المطلقة (مم)، pn: ضغط التشغيل الاسمي (بار)، a: سرعة موجة الضغط (م/ث)\n// القيم نموذجية من المراجع الهندسية الشائعة (Crane TP-410، كتب الهيدروليك)\n// ═══════════════════════════════════════════════════════════════\nexport const MATERIALS = {\n  pvc:   { name: 'PVC',         e: 0.0015, pn: 10, a: 400,  tMax: 45 },\n  steel: { name: 'حديد أسود',   e: 0.045,  pn: 40, a: 1200, tMax: 120 },\n  galv:  { name: 'حديد مجلفن',  e: 0.15,   pn: 25, a: 1150, tMax: 120 },\n  cast:  { name: 'زهر',         e: 0.26,   pn: 16, a: 1100, tMax: 120 },\n};\n\n// تخفيض ضغط PVC مع الحرارة (معامل × PN)\nexport function pvcDerate(tC) {\n  if (tC \u003c= 25) return 1;\n  if (tC \u003c= 35) return 0.8;\n  if (tC \u003c= 45) return 0.63;\n  return 0.5;\n}\n\n// القطر الداخلي (مم)\nexport const DIAMETERS = [20, 25, 32, 40, 50, 63, 75, 90, 110];\n\n// معاملات الفقد الموضعي K\nexport const FITTINGS = {\n  elbow90: 0.9,\n  footValve: 2.5,   // صمام قدم بمصفاة\n  entrance: 0.5,\n  checkValve: 2.0,  // صمام عدم رجوع\n  gateValve: 0.2,\n  exit: 1.0,\n};\n\n// حدود السرعة الموصى بها (م/ث)\nexport const VELOCITY = {\n  suction:   { min: 0.6, max: 1.5, hard: 2.0, design: 1.2 },\n  discharge: { min: 0.6, max: 2.5, design: 1.2 },\n};\n"},"/assets/js/data/pumps.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// كتالوج المضخات — بيانات منشورة من الشركة المصنّعة\n// لإضافة مضخة: أضف عنصراً إلى PUMPS بنفس الشكل، واذكر مصدرها في SOURCES.\n// النقاط curve: [التدفق لتر/دقيقة, الضاغط متر] كما في جدول الكتالوج حرفياً.\n// ═══════════════════════════════════════════════════════════════\n\nexport const SOURCES = {\n  cp60: {\n    title: 'Pedrollo CP 0.25–2.2 kW — Datasheet 60 Hz',\n    url: 'https://www.pedrollo.com/wp-content/uploads/schede-tecniche/EN/CP_EN-datasheet_60Hz.pdf',\n    publisher: 'Pedrollo S.p.A. — الموقع الرسمي',\n    hz: 60, rpm: 3450,\n    notes: 'الجدول عند HS = 0 م، وتفاوت المنحنيات حسب EN ISO 9906 Grade 3B. أقصى سحب مانومتري 7 م. ضغط الجسم 6 بار للموديلات 600–620 و10 بار للموديلات 650–670. حرارة السائل −10 إلى +90°م.',\n  },\n  jsw2_60: {\n    title: 'Pedrollo JSW2 — Catálogo general 60 Hz (ص 104–105)',\n    url: 'https://cdn.shopify.com/s/files/1/0604/8697/5686/files/JSW2-60Hz-ES.pdf',\n    publisher: 'صفحة من كتالوج Pedrollo العام 60 Hz منشورة لدى موزّع',\n    hz: 60, rpm: 3450,\n    notes: 'مضخات JET ذاتية التحضين. أقصى سحب 9 م (HS). حرارة السائل حتى +40°م. أقصى ضغط في الجسم 6 بار.',\n  },\n  sr4_60: {\n    title: 'Pedrollo 4SR-S 4\" submersible — Datasheet 60 Hz',\n    url: 'https://www.pedrollo.com/wp-content/uploads/schede-tecniche/EN/4SR_EN-datasheet_60Hz.pdf',\n    publisher: 'Pedrollo S.p.A. — الموقع الرسمي',\n    hz: 60, rpm: 3450,\n    notes: 'مضخة آبار 4 بوصة. حرارة السائل حتى +40°م، رمل حتى 200 غ/م³. عند تركيبها في خزان (لا بئر) يلزم غلاف تبريد (flow sleeve) ليمر الماء على المحرك.',\n  },\n};\n\n// type: surface | selfprime | sub\n// qBep (اختياري، م³/س): تدفق أفضل كفاءة إن عُرف. في 4SR الرقم قبل G هو التدفق عند أفضل كفاءة بالغالون الأمريكي/دقيقة (25G ≈ 5.68 م³/س)\n// maxLift: أقصى سحب مانومتري من الكتالوج (م)، maxBar: أقصى ضغط للجسم، tMax: أقصى حرارة سائل\nexport const PUMPS = [\n  // ── سطحية طرد مركزي — Pedrollo CP، 60 Hz ──\n  { id: 'cpm600', model: 'CPm 600', type: 'surface', kw: 0.37, src: 'cp60', maxLift: 7, maxBar: 6, tMax: 90, ports: '1\" × 1\"',\n    curve: [[0,22],[10,21],[20,20],[40,18],[60,15],[80,11]] },\n  { id: 'cpm610', model: 'CPm 610', type: 'surface', kw: 0.60, src: 'cp60', maxLift: 7, maxBar: 6, tMax: 90, ports: '1\" × 1\"',\n    curve: [[0,28.5],[10,28],[20,27],[40,25],[60,22],[80,19],[90,17]] },\n  { id: 'cpm620', model: 'CPm 620', type: 'surface', kw: 0.75, src: 'cp60', maxLift: 7, maxBar: 6, tMax: 90, ports: '1\" × 1\"',\n    curve: [[0,35],[10,34],[20,33],[40,31],[60,28.5],[80,25.5],[90,23.5],[100,21]] },\n  { id: 'cpm650', model: 'CPm 650', type: 'surface', kw: 1.1, src: 'cp60', maxLift: 7, maxBar: 10, tMax: 90, ports: '1¼\" × 1\"',\n    curve: [[0,40],[20,39],[40,38],[60,36],[80,33.1],[90,31.2],[100,28.8],[110,26]] },\n  { id: 'cpm660', model: 'CPm 660', type: 'surface', kw: 1.5, src: 'cp60', maxLift: 7, maxBar: 10, tMax: 90, ports: '1¼\" × 1\"',\n    curve: [[0,48],[20,47.5],[40,46],[60,44],[80,41],[90,39.5],[100,37.5],[110,35],[120,32]] },\n  { id: 'cpm670', model: 'CPm 670', type: 'surface', kw: 2.2, src: 'cp60', maxLift: 7, maxBar: 10, tMax: 90, ports: '1¼\" × 1\"',\n    curve: [[0,56],[20,55.5],[40,54.5],[60,52.5],[80,50],[90,48.5],[100,46.5],[110,44],[120,41.5],[130,38]] },\n\n  // ── ذاتية التحضين JET — Pedrollo JSW2، 60 Hz ──\n  { id: 'jswm2c', model: 'JSWm 2C', type: 'selfprime', kw: 0.75, src: 'jsw2_60', maxLift: 9, maxBar: 6, tMax: 40, ports: '1\" × 1\"',\n    curve: [[0,50],[5,47],[10,44],[20,38.5],[25,36],[30,34],[40,29.5],[45,27.5],[50,26],[60,22.5],[70,20]] },\n  { id: 'jswm2b', model: 'JSWm 2B', type: 'selfprime', kw: 0.90, src: 'jsw2_60', maxLift: 9, maxBar: 6, tMax: 40, ports: '1\" × 1\"',\n    curve: [[0,58],[5,55],[10,52],[20,46.5],[25,43.5],[30,41],[40,36.5],[45,34],[50,32],[60,28],[70,25]] },\n  { id: 'jswm2a', model: 'JSWm 2A', type: 'selfprime', kw: 1.1, src: 'jsw2_60', maxLift: 9, maxBar: 6, tMax: 40, ports: '1\" × 1\"',\n    curve: [[0,64],[5,61],[10,57.5],[20,51.5],[25,49],[30,46],[40,41],[45,38.5],[50,36],[60,32],[70,29]] },\n\n  // ── غاطسة 4\" — Pedrollo 4SR-S، 60 Hz ──\n  { id: '4sr25g5', qBep: 5.68, model: '4SRm 25G/5-S', type: 'sub', kw: 0.37, src: 'sr4_60', stages: 3, maxBar: null, tMax: 40, ports: '1¼\" NPT',\n    curve: [[0,34.5],[20,33.5],[40,32],[60,29.5],[80,25.4],[100,19.8],[120,13],[130,9]] },\n  { id: '4sr13g5', qBep: 2.95, model: '4SRm 13G/5-S', type: 'sub', kw: 0.37, src: 'sr4_60', stages: 5, maxBar: null, tMax: 40, ports: '1¼\" NPT',\n    curve: [[0,58.5],[10,55],[20,52.5],[30,49.5],[40,46],[50,41],[60,34],[70,26],[75,21.5]] },\n  { id: '4sr25g7', qBep: 5.68, model: '4SRm 25G/7-S', type: 'sub', kw: 0.55, src: 'sr4_60', stages: 5, maxBar: null, tMax: 40, ports: '1¼\" NPT',\n    curve: [[0,58],[20,56],[40,53.5],[60,49],[80,42.5],[100,33],[120,21.6],[130,15.5]] },\n  { id: '4sr25g10', qBep: 5.68, model: '4SRm 25G/10-S', type: 'sub', kw: 0.75, src: 'sr4_60', stages: 6, maxBar: null, tMax: 40, ports: '1¼\" NPT',\n    curve: [[0,69.5],[20,67],[40,64],[60,59],[80,51],[100,39.5],[120,26],[130,18.5]] },\n  { id: '4sr13g7', qBep: 2.95, model: '4SRm 13G/7-S', type: 'sub', kw: 0.55, src: 'sr4_60', stages: 7, maxBar: null, tMax: 40, ports: '1¼\" NPT',\n    curve: [[0,82],[10,77],[20,74],[30,69.5],[40,64.5],[50,57.5],[60,48],[70,36.5],[75,30]] },\n  { id: '4sr25g15', qBep: 5.68, model: '4SRm 25G/15-S', type: 'sub', kw: 1.1, src: 'sr4_60', stages: 8, maxBar: null, tMax: 40, ports: '1¼\" NPT',\n    curve: [[0,92],[20,90],[40,85],[60,78],[80,67.5],[100,53],[120,34.5],[130,24.5]] },\n];\n\nexport const PUMP_TYPES = {\n  surface:   { name: 'سطحية',          note: 'طرد مركزي فوق الأرض. تحتاج صمام قدم يبقيها ممتلئة، وأقصى سحب في الكتالوج 7 م.' },\n  selfprime: { name: 'ذاتية التحضين',  note: 'نوع JET يطرد الهواء وحده، يسحب حتى 9 م. تدفق أقل من الطرد المركزي بنفس القدرة.' },\n  sub:       { name: 'غاطسة',          note: 'تُركَّب داخل الخزان فلا سحب ولا تكهف. في الخزان تحتاج غلاف تبريد للمحرك.' },\n};\n\nexport const byId = id => PUMPS.find(p => p.id === id);\nexport const ofType = t => PUMPS.filter(p => p.type === t);\n"},"/assets/js/engine/checks.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// الفحوصات الهندسية — كل فحص مستقل؛ لإضافة فحص أضف دالة إلى RULES\n// كل دالة تُرجع null أو { level: ok|warn|bad, title, detail, fixes:[{label, apply(state)}] }\n// ═══════════════════════════════════════════════════════════════\nimport { MATERIALS, DIAMETERS, VELOCITY } from '../data/materials.js';\nimport { PUMP_TYPES, byId } from '../data/pumps.js';\nimport { recommendPump, recommendDiameters, requiredLengths, fitToCurve } from './recommend.js';\nimport { n1, n2, n0 } from '../core/format.js';\n\nconst fixLengths = { label: 'اضبط الأطوال المطلوبة', apply: s => { const L = requiredLengths(s, byId(s.pump.id).type); s.suction.L = L.suction; s.discharge.L = L.discharge; s.autoLength = true; } };\nconst fixThrottle = { label: 'اضبط صمام الخنق وقطر الدفع', apply: s => fitToCurve(s) };\nconst fixPump = { label: 'طبّق المضخة الموصى بها', apply: s => { s.pump.id = recommendPump(s, byId(s.pump.id).type); } };\nconst switchType = (t, label) => ({ label, apply: s => { s.pump.id = recommendPump(s, t); const L = requiredLengths(s, t); s.suction.L = L.suction; s.discharge.L = L.discharge; } });\n\nconst RULES = [\n  R => R.noLift && { level: 'bad', title: 'المضخة لا تكفي للرفع',\n    detail: `أقصى ضاغط للمضخة ${n1(R.C.H0)} م والرفع الساكن ${n1(R.g.Hs)} م، فلن يصل الماء إلى الخزان العلوي.`, fixes: [fixPump] },\n\n  R => R.air && { level: 'bad', title: 'ماسورة السحب لا تصل إلى الماء',\n    detail: `طولها ${n1(R.s.suction.L)} م والمطلوب ${n1(R.g.suctionReq)} م على الأقل. المضخة ستسحب هواءً وتدور جافة فيتلف مانع التسرب.`, fixes: [fixLengths] },\n\n  R => R.dischargeShort && { level: 'bad', title: 'ماسورة الدفع قصيرة',\n    detail: `طولها ${n1(R.s.discharge.L)} م والمطلوب ${n1(R.g.dischargeReq)} م لتصل إلى مدخل الخزان العلوي.`, fixes: [fixLengths] },\n\n  R => R.tempC > R.pump.tMax && { level: 'bad', title: 'حرارة الماء فوق حد المضخة',\n    detail: `الكتالوج يحدد حرارة السائل حتى ${R.pump.tMax}°م، والتصميم ${n0(R.tempC)}°م.`, fixes: [switchType('surface', 'استخدم مضخة طرد مركزي CP (حتى 90°م)')] },\n\n  R => !R.noLift && !R.air && (() => {\n    const k = R.q / R.D.qReq;\n    return { level: k >= 1 ? 'ok' : k >= 0.8 ? 'warn' : 'bad', title: 'التدفق مقابل الطلب',\n      detail: `نقطة التشغيل ${n2(R.q)} م³/س، والمطلوب ${n2(R.D.qReq)} م³/س (استهلاك ${n1(R.D.daily)} م³/يوم خلال ${n0(R.s.env.pumpingHours)} ساعات ضخ).`,\n      fixes: k \u003c 1 ? [fixPump, { label: `زِد ساعات الضخ إلى ${Math.min(24, Math.ceil(R.D.daily / Math.max(R.q, 0.1)))}`, apply: s => { s.env.pumpingHours = Math.min(24, Math.ceil(R.D.daily / Math.max(R.q, 0.1))); } }] : [] };\n  })(),\n\n  R => R.runout && { level: 'bad', title: 'التشغيل بعد نهاية المنحنى المنشور',\n    detail: 'منحنى النظام يقطع منحنى المضخة بعد آخر نقطة في جدول الكتالوج (Run-out). المضخة تعمل بتدفق عالٍ وكفاءة متدنية وخطر تكهف وحمل زائد على المحرك.',\n    fixes: [fixThrottle, fixPump] },\n\n  R => !R.noLift && !R.air && !R.runout && { level: (R.r >= 0.7 && R.r \u003c= 1.2) ? 'ok' : (R.r >= 0.4 && R.r \u003c= 1.6) ? 'warn' : 'bad',\n    title: 'القرب من نقطة أفضل كفاءة (BEP)',\n    detail: `التشغيل عند ${n0(R.r * 100)}٪ من تدفق BEP التقديري (${n2(R.C.qBep)} م³/س). النطاق المفضل 70–120٪ (Hydraulic Institute)؛ خارجه يزيد الاهتزاز وتآكل المحامل. BEP هنا تقديري، فاعتبر الحكم إرشادياً.`,\n    fixes: R.r > 1.2 ? [fixThrottle, fixPump] : R.r \u003c 0.7 ? [fixPump] : [] },\n\n  R => !R.sub && !R.noLift && !R.air && (() => {\n    const m = R.margin;\n    return { level: m >= 1 ? 'ok' : m >= 0.5 ? 'warn' : 'bad', title: 'التكهف (NPSH)',\n      detail: `NPSH المتاح ${n2(R.npsha)} م، والمطلوب ≈ ${n2(R.npshr)} م (تقديري)، والهامش ${n2(m)} م. يُفضَّل هامش 1 م أو أكثر.`,\n      fixes: m \u003c 1 ? [\n        { label: 'اخفض المضخة إلى الأرض', apply: s => { s.pump.z = 0; s.pump.x = Math.min(s.pump.x, 2); } },\n        { label: 'كبّر قطر السحب', apply: s => { s.suction.d = recommendDiameters(Math.max(R.q, R.D.qReq)).suction; } },\n        switchType('sub', 'استخدم مضخة غاطسة'),\n      ] : [] };\n  })(),\n\n  R => !R.sub && R.pump.maxLift && { level: R.g.lift \u003c= R.pump.maxLift ? 'ok' : 'bad', title: 'السحب مقابل حد الكتالوج',\n    detail: `المضخة فوق سطح الماء بـ ${n1(R.g.lift)} م، وأقصى سحب في كتالوج ${R.pump.model} هو ${R.pump.maxLift} م.`,\n    fixes: R.g.lift > R.pump.maxLift ? [switchType('selfprime', 'استخدم ذاتية التحضين (9 م)'), switchType('sub', 'استخدم مضخة غاطسة')] : [] },\n\n  R => R.pump.type === 'surface' && R.g.lift > 4 && { level: 'warn', title: 'التحضين',\n    detail: `مضخة طرد مركزي تسحب من ${n1(R.g.lift)} م تحتها؛ أي تسريب هواء في صمام القدم يفقدها التحضين.`,\n    fixes: [switchType('selfprime', 'حوّل إلى ذاتية التحضين')] },\n\n  R => R.sub && { level: 'info', title: 'تبريد المحرك الغاطس',\n    detail: 'مضخات 4SR مصممة للآبار حيث يمر الماء حول المحرك. داخل خزان يجب تركيب غلاف تبريد (flow sleeve) وإلا يسخن المحرك.', fixes: [] },\n\n  R => R.L.s && !R.air && (() => {\n    const v = R.L.s.V, lim = VELOCITY.suction;\n    return { level: v \u003c= lim.max ? 'ok' : v \u003c= lim.hard ? 'warn' : 'bad', title: 'سرعة السحب',\n      detail: `${n2(v)} م/ث في قطر ${R.s.suction.d} مم. الموصى به ${lim.min}–${lim.max} م/ث.`,\n      fixes: v > lim.max ? [{ label: 'طبّق القطر الموصى به', apply: s => { s.suction.d = recommendDiameters(R.q).suction; } }] : [] };\n  })(),\n\n  R => !R.noLift && (() => {\n    const v = R.L.d.V, lim = VELOCITY.discharge;\n    return { level: (v >= lim.min && v \u003c= lim.max) ? 'ok' : 'warn', title: 'سرعة الدفع',\n      detail: `${n2(v)} م/ث في قطر ${R.s.discharge.d} مم. النطاق المناسب ${lim.min}–${lim.max} م/ث.`,\n      fixes: (v \u003c lim.min || v > lim.max) ? [{ label: 'طبّق القطر الموصى به', apply: s => { s.discharge.d = recommendDiameters(R.q).discharge; } }] : [] };\n  })(),\n\n  R => !R.sub && R.s.suction.d \u003c R.s.discharge.d && { level: 'warn', title: 'قطر السحب أصغر من الدفع',\n    detail: 'القاعدة العملية أن يساوي قطر السحب قطر الدفع أو يزيد عليه درجة لتقليل فقد السحب.',\n    fixes: [{ label: 'ساوِ قطر السحب', apply: s => { s.suction.d = s.discharge.d; } }] },\n\n  R => R.q > 0 && R.s.discharge.valveK > 0 && { level: 'info', title: 'صمام الخنق',\n    detail: `صمام البوابة على الدفع مضبوط بمعامل K = ${n1(R.s.discharge.valveK)} ليبقى التشغيل داخل المنحنى المنشور. يُضبط عند التركيب بمقياس ضغط على مخرج المضخة حتى يقرأ ≈ ${n1(R.h)} م (${n2(R.h * 0.0979)} بار).`, fixes: [] },\n  R => R.q > 0 && { level: 'info', title: 'قدرة المحرك',\n    detail: `قدرة العمود عند التشغيل ≈ ${n2(R.shaftKw)} ك.واط من ${R.pump.kw} ك.واط (P2 في الكتالوج). الكفاءة ≈ ${n0(R.eta * 100)}٪ (تقديرية).`, fixes: [] },\n\n  R => R.q > 0 && { level: R.pMaxBar \u003c= R.pnBar ? 'ok' : 'bad', title: 'الطرق المائي وضغط الماسورة',\n    detail: `ارتفاع الضغط عند إغلاق مفاجئ ≈ ${n1(R.surge)} م (جوكوفسكي). أقصى ضغط ${n1(R.pMaxBar)} بار، وتحمّل ${MATERIALS[R.s.discharge.mat].name} ${n1(R.pnBar)} بار${R.derate \u003c 1 ? ' بعد تخفيض الحرارة' : ''}. صمام عدم رجوع زنبركي سريع الإغلاق يقلل الطرق.`,\n    fixes: R.pMaxBar > R.pnBar ? [{ label: 'حوّل الدفع إلى مجلفن', apply: s => { s.discharge.mat = 'galv'; } }] : [] },\n\n  R => R.pump.maxBar && R.q > 0 && R.pMaxBar > R.pump.maxBar && { level: 'warn', title: 'ضغط جسم المضخة',\n    detail: `أقصى ضغط متوقع ${n1(R.pMaxBar)} بار وجسم ${R.pump.model} مصمم لـ ${R.pump.maxBar} بار.`, fixes: [] },\n\n  R => R.tempC > 45 && (R.s.discharge.mat === 'pvc' || (!R.sub && R.s.suction.mat === 'pvc')) && { level: 'bad', title: 'الحرارة ومادة PVC',\n    detail: `ماء ${n0(R.tempC)}°م يتجاوز حد PVC العادي (45°م).`,\n    fixes: [{ label: 'حوّل المواسير إلى مجلفن', apply: s => { s.discharge.mat = 'galv'; s.suction.mat = 'galv'; } }] },\n\n  R => { const k = R.s.roof.vol / R.D.roofRec;\n    return { level: k >= 0.9 ? 'ok' : 'warn', title: 'سعة الخزان العلوي',\n      detail: `${n1(R.s.roof.vol)} م³، والموصى به ${n1(R.D.roofRec)} م³ (نصف الاستهلاك اليومي).`,\n      fixes: k \u003c 0.9 ? [{ label: 'طبّق السعة', apply: s => { s.roof.vol = R.D.roofRec; } }] : [] }; },\n\n  R => { const k = R.s.ground.vol / R.D.groundRec;\n    return { level: k >= 0.9 ? 'ok' : 'warn', title: 'سعة الخزان الأرضي',\n      detail: `${n1(R.s.ground.vol)} م³، والموصى به ${n1(R.D.groundRec)} م³ (استهلاك يوم كامل).`,\n      fixes: k \u003c 0.9 ? [{ label: 'طبّق السعة', apply: s => { s.ground.vol = R.D.groundRec; } }] : [] }; },\n];\n\nconst ORDER = { bad: 0, warn: 1, ok: 2, info: 3 };\n\nexport function runChecks(R, s) {\n  const ctx = Object.assign({}, R, { s });\n  return RULES.map(f => f(ctx)).filter(Boolean).sort((a, b) => ORDER[a.level] - ORDER[b.level]);\n}\n\nexport function verdict(list) {\n  const bad = list.filter(c => c.level === 'bad').length, warn = list.filter(c => c.level === 'warn').length;\n  return { level: bad ? 'bad' : warn ? 'warn' : 'ok', bad, warn };\n}\n\nexport { PUMP_TYPES };\n"},"/assets/js/engine/demand.js":{"type":"text/javascript; charset=utf-8","text":"// الطلب اليومي وسعات الخزانات والهندسة الرأسية للموقع\nimport { BUILDINGS, TANK_RULES } from '../data/buildings.js';\n\nexport function demand(s) {\n  const B = s.building, T = BUILDINGS[B.type];\n  const people = B.floors * B.perFloor;\n  const daily = people * T.rate / 1000;                     // م³/يوم\n  const qReq = Math.max(1, daily / s.env.pumpingHours);     // م³/س\n  const half = v => Math.ceil(v * 2) / 2;\n  return {\n    people, daily, qReq,\n    roofRec: Math.max(TANK_RULES.roofMin, half(daily * TANK_RULES.roofShare)),\n    groundRec: Math.max(TANK_RULES.groundMin, Math.ceil(daily * TANK_RULES.groundShare)),\n  };\n}\n\n// المناسيب بالنسبة لسطح الأرض ±0.00\nexport function geometry(s, type) {\n  const B = s.building, sub = type === 'sub';\n  const roofTop = B.floors * B.floorH;                     // منسوب السطح\n  const inlet = roofTop + TANK_RULES.roofInletAboveRoof;   // منسوب مدخل الخزان العلوي\n  const d = s.ground.depth;                                // عمق سطح الماء تحت الأرض\n  const pumpZ = sub ? -(d + 0.6) : s.pump.z;               // منسوب محور المضخة\n  const lift = sub ? -0.6 : pumpZ + d;                     // المضخة فوق سطح الماء (+) أو تحته (−)\n  const suctionReq = sub ? 0 : s.pump.x + 1 + pumpZ + d + 0.4;\n  const dischargeReq = sub\n    ? (d + 0.6) + (s.site + 1) + inlet + 0.8\n    : (s.site - s.pump.x) + (inlet - pumpZ) + 1.5;\n  return { roofTop, inlet, d, pumpZ, lift, suctionReq, dischargeReq, Hs: inlet + d, sub };\n}\n"},"/assets/js/engine/hydraulics.js":{"type":"text/javascript; charset=utf-8","text":"// فقد الاحتكاك والفقد الموضعي في المواسير\nimport { G } from './water.js';\nimport { MATERIALS, FITTINGS } from '../data/materials.js';\n\n// معامل الاحتكاك: صفائحي 64/Re، مضطرب Swamee–Jain\nexport function frictionFactor(Re, relRough) {\n  if (Re \u003c 1) return 0;\n  if (Re \u003c 2300) return 64 / Re;\n  return 0.25 / Math.log10(relRough / 3.7 + 5.74 / Re ** 0.9) ** 2;\n}\n\n// مجموع K لماسورة السحب والدفع\nexport function suctionK(pipe, selfPriming) {\n  return (selfPriming ? 0 : FITTINGS.footValve) + FITTINGS.entrance + pipe.elbows * FITTINGS.elbow90;\n}\nexport function dischargeK(pipe) {\n  return FITTINGS.checkValve + FITTINGS.gateValve + FITTINGS.exit + pipe.elbows * FITTINGS.elbow90 + (pipe.valveK || 0);\n}\n\n// Q بـ م³/ث → الفقد Darcy–Weisbach\nexport function pipeLoss(Q, pipe, K, w) {\n  const D = pipe.d / 1000, A = Math.PI * D * D / 4, V = Q / A;\n  const Re = w.rho * V * D / w.mu;\n  const f = frictionFactor(Re, MATERIALS[pipe.mat].e / 1000 / D);\n  const hv = V * V / (2 * G);\n  const hf = f * pipe.L / D * hv, hm = K * hv;\n  return { V, Re, f, hf, hm, h: hf + hm };\n}\n\n// أصغر قطر يحقق سرعة لا تتجاوز vmax عند تدفق q (م³/س)\nexport function sizeDiameter(qM3h, vmax, list) {\n  const Q = qM3h / 3600;\n  return list.find(d => Q / (Math.PI * (d / 1000) ** 2 / 4) \u003c= vmax) || list[list.length - 1];\n}\n"},"/assets/js/engine/pumpcurve.js":{"type":"text/javascript; charset=utf-8","text":"// منحنى المضخة من نقاط الكتالوج\n// • الضاغط H(Q): استيفاء خطي بين النقاط المنشورة، بلا استقراء خارجها\n// • قدرة العمود وNPSHr: تقديريتان لأن جداول هذه الموديلات لا تنشرهما\n//   قدرة العمود: خطية من ~45٪ من P2 عند Q=0 إلى P2 عند آخر نقطة (سلوك مضخات الطرد المركزي القطرية)\n//   الكفاءة = القدرة الهيدروليكية ÷ قدرة العمود\nimport { G } from './water.js';\n\nconst RHO = 998, SHUTOFF_POWER = 0.45;\n\nexport function curveOf(pump) {\n  const pts = pump.curve.map(([lpm, h]) => [lpm * 0.06, h]); // لتر/دقيقة → م³/س\n  const qMax = pts[pts.length - 1][0];\n  const H = q => {\n    if (q \u003c= 0) return pts[0][1];\n    for (let i = 1; i \u003c pts.length; i++) {\n      if (q \u003c= pts[i][0]) { const [q0, h0] = pts[i - 1], [q1, h1] = pts[i]; return h0 + (h1 - h0) * (q - q0) / (q1 - q0); }\n    }\n    return pts[pts.length - 1][1];\n  };\n  const P2 = pump.kw;\n  const shaftKw = q => P2 * (SHUTOFF_POWER + (1 - SHUTOFF_POWER) * Math.min(q, qMax) / qMax);\n  const eta = q => Math.max(0.05, Math.min(0.85, (RHO * G * (q / 3600) * H(q) / 1000) / shaftKw(q)));\n  // BEP: من بيانات الموديل إن وُجدت (pump.qBep م³/س)، وإلا 65٪ من آخر تدفق في الجدول\n  // (جداول الكتالوج تمتد عادة إلى نحو 120–130٪ من BEP)\n  const qBep = pump.qBep || 0.65 * qMax, etaBep = eta(qBep);\n  const npshr = q => pump.type === 'sub' ? 0 : (pump.type === 'selfprime' ? 1.2 : 1.8) + 2.2 * (q / qMax) ** 2;\n  return { pts, qMax, H, qBep, etaBep, eta, shaftKw, npshr, H0: pts[0][1] };\n}\n"},"/assets/js/engine/recommend.js":{"type":"text/javascript; charset=utf-8","text":"// اختيار المضخة والأقطار الموصى بها\nimport { solve } from './solve.js';\nimport { demand, geometry } from './demand.js';\nimport { sizeDiameter } from './hydraulics.js';\nimport { DIAMETERS, VELOCITY } from '../data/materials.js';\nimport { ofType, byId } from '../data/pumps.js';\nimport { curveOf } from './pumpcurve.js';\n\nconst clone = o => JSON.parse(JSON.stringify(o));\nconst MAX_THROTTLE_K = 150;\n\n// أطوال المواسير المطلوبة للهندسة الحالية (مقرّبة لأعلى نصف متر)\nexport function requiredLengths(s, type) {\n  const g = geometry(s, type), up = v => Math.ceil(v * 2) / 2;\n  return { suction: up(g.suctionReq + 0.3), discharge: up(g.dischargeReq + 0.5) };\n}\n\n// معامل صمام الخنق اللازم ليعمل التصميم داخل المنحنى المنشور وقرب BEP\nexport function throttleK(s) {\n  if (!s.pump) return 0;\n  const c = clone(s); c.discharge.valveK = 0;\n  const R = solve(c), C = R.C;\n  if (R.noLift || R.air) return 0;\n  if (!R.runout && R.r \u003c= 1.25) return 0;\n  const target = Math.min(C.qMax * 0.95, Math.max(R.D.qReq, C.qBep * 1.15));\n  const excess = C.H(target) - R.Hsys(target);\n  if (excess \u003c= 0) return 0;\n  const A = Math.PI * (c.discharge.d / 1000) ** 2 / 4, V = target / 3600 / A;\n  const K = Math.ceil(excess * 2 * 9.81 / (V * V) * 2) / 2;\n  return K > MAX_THROTTLE_K ? 0 : K;   // خنق أكبر من هذا إهدار للطاقة: الأفضل مضخة أصغر\n}\n\n// يجعل التشغيل داخل المنحنى المنشور: صمام خنق، وإن لزم خنق مفرط يُصغَّر قطر الدفع درجة أو أكثر (سرعة ≤ 2.5 م/ث)\nexport function fitToCurve(s) {\n  if (!s.pump || !s.discharge) return;\n  s.discharge.valveK = 0;\n  const start = DIAMETERS.indexOf(s.discharge.d);\n  for (let i = start; i >= 0; i--) {\n    s.discharge.d = DIAMETERS[i];\n    const R = solve(s);\n    if (R.L.d.V > VELOCITY.discharge.max) { s.discharge.d = DIAMETERS[Math.min(start, i + 1)]; break; }\n    if (!R.runout && R.r \u003c= 1.25) return;\n    const K = throttleK(s);\n    if (K > 0) { s.discharge.valveK = K; return; }\n  }\n  s.discharge.valveK = throttleK(s);\n}\n\nexport function defaultPipes(s, pumpId) {\n  const D = demand(s), C = curveOf(byId(pumpId));\n  const qd = Math.max(D.qReq, C.qBep);\n  return {\n    suction:   { L: 0, d: sizeDiameter(qd, VELOCITY.suction.design, DIAMETERS), mat: 'pvc', elbows: 2 },\n    discharge: { L: 0, d: sizeDiameter(qd, VELOCITY.discharge.design, DIAMETERS), mat: 'pvc', elbows: 4 },\n  };\n}\n\n// تصميم تجريبي بمضخة مختلفة دون المساس بالحالة الأصلية\nexport function trial(s, pumpId) {\n  const c = clone(s), prev = c.pump, p = byId(pumpId);\n  c.pump = { id: pumpId, x: prev ? prev.x : Math.round(c.site * 0.35 * 2) / 2, z: prev ? prev.z : 0.3 };\n  if (!c.suction) Object.assign(c, defaultPipes(c, pumpId));\n  if (!prev || byId(prev.id).type !== p.type || c.autoLength) {\n    const L = requiredLengths(c, p.type); c.suction.L = L.suction; c.discharge.L = L.discharge;\n  }\n  if (c.autoLength || !prev) fitToCurve(c);\n  return solve(c);\n}\n\n// الأولوية: يعمل بأمان ← يحقق الطلب ← قرب BEP ← أقل خنق ← أصغر محرك\nexport function score(R) {\n  if (R.noLift || R.air) return -1e9;\n  let sc = 0;\n  if (R.tempC > R.pump.tMax) sc -= 2000;\n  if (R.runout) sc -= 500;\n  if (!R.sub && (R.margin \u003c 0.5 || R.g.lift > (R.pump.maxLift || 99))) sc -= 800;\n  if (R.q \u003c R.D.qReq) sc -= 1000 * (1 - R.q / R.D.qReq);\n  sc -= 300 * (R.r \u003c 0.7 ? 0.7 - R.r : R.r > 1.2 ? R.r - 1.2 : 0);\n  if (R.pMaxBar > R.pnBar) sc -= 100;\n  sc -= 0.5 * (R.s?.discharge?.valveK || 0);\n  sc -= 20 * R.pump.kw;\n  return sc;\n}\n\nexport function recommendPump(s, type) {\n  let best = null, bs = -Infinity;\n  for (const p of ofType(type)) {\n    const sc = score(trial(s, p.id));\n    if (sc > bs) { bs = sc; best = p.id; }\n  }\n  return best;\n}\n\nexport function recommendDiameters(q) {\n  return {\n    suction: sizeDiameter(q, VELOCITY.suction.design, DIAMETERS),\n    discharge: sizeDiameter(q, VELOCITY.discharge.design, DIAMETERS),\n  };\n}\n"},"/assets/js/engine/solve.js":{"type":"text/javascript; charset=utf-8","text":"// الحل الكامل للتصميم: نقطة التشغيل وكل المؤشرات\nimport { G, water, atmPressure } from './water.js';\nimport { pipeLoss, suctionK, dischargeK } from './hydraulics.js';\nimport { curveOf } from './pumpcurve.js';\nimport { demand, geometry } from './demand.js';\nimport { MATERIALS, pvcDerate } from '../data/materials.js';\nimport { byId } from '../data/pumps.js';\n\n// معامل خدمة المحرك وكفاءته الكهربائية التقريبية\nconst SERVICE_FACTOR = 1.15, MOTOR_EFF = 0.8;\n\nexport function solve(s, pumpId) {\n  const pump = byId(pumpId || s.pump.id);\n  const C = curveOf(pump);\n  const w = water(s.env.waterTempC), pa = atmPressure(s.env.altitudeM);\n  const g = geometry(s, pump.type), sub = g.sub;\n  const Ks = suctionK(s.suction, pump.type === 'selfprime'), Kd = dischargeK(s.discharge);\n\n  const losses = q => {\n    const Q = Math.max(q, 1e-7) / 3600;\n    const d = pipeLoss(Q, s.discharge, Kd, w);\n    const su = sub ? null : pipeLoss(Q, s.suction, Ks, w);\n    return { d, s: su, h: d.h + (su ? su.h : 0) };\n  };\n  const Hsys = q => g.Hs + losses(q).h;\n\n  // نقطة التشغيل بالتنصيف على مجال المنحنى المنشور\n  const noLift = C.H(0) \u003c= g.Hs;\n  let q = 0, runout = false;\n  if (!noLift) {\n    if (C.H(C.qMax) > Hsys(C.qMax)) { q = C.qMax; runout = true; }\n    else {\n      let a = 0, b = C.qMax;\n      for (let i = 0; i \u003c 60; i++) { const m = (a + b) / 2; (C.H(m) > Hsys(m)) ? a = m : b = m; }\n      q = (a + b) / 2;\n    }\n  }\n  const h = C.H(q), L = losses(q), eta = C.eta(q), r = q / C.qBep;\n  const shaftKw = q > 0 ? C.shaftKw(q) : 0;\n\n  // NPSH\n  const hAtm = (pa - w.pv) / (w.rho * G);\n  const npsha = sub ? hAtm + 0.6 : hAtm - g.lift - (L.s ? L.s.h : 0);\n  const npshr = C.npshr(q);\n\n  // المواسير القصيرة\n  const suctionShort = !sub && s.suction.L \u003c g.suctionReq - 0.05;\n  const dischargeShort = s.discharge.L \u003c g.dischargeReq - 0.05;\n\n  // الطرق المائي (جوكوفسكي) وضغط الماسورة\n  const mat = MATERIALS[s.discharge.mat];\n  const derate = s.discharge.mat === 'pvc' ? pvcDerate(s.env.waterTempC) : 1;\n  const surge = mat.a * L.d.V / G;\n  const pMaxBar = w.rho * G * Math.max(C.H0, h + (q > 0 ? surge : 0)) / 1e5;\n  const pnBar = mat.pn * derate;\n\n  // الطاقة\n  const D = demand(s);\n  const runH = q > 0 ? D.daily / q : Infinity;\n  const kwhDay = shaftKw / MOTOR_EFF * Math.min(runH, 24);\n  const costYear = kwhDay * 365 * s.env.tariff;\n\n  return {\n    pump, C, w, pa, g, sub, q, h, L, eta, r, shaftKw, runout, noLift,\n    hAtm, npsha, npshr, margin: npsha - npshr,\n    maxLift: hAtm - (L.s ? L.s.h : 0) - npshr - 0.5,\n    suctionShort, dischargeShort,\n    air: suctionShort,\n    leak: dischargeShort && q > 0 && !suctionShort,\n    cavitation: !sub && q > 0 && !suctionShort && npsha \u003c npshr,\n    flows: q > 0 && !suctionShort && !dischargeShort,\n    surge, pMaxBar, pnBar, derate,\n    D, runH, kwhDay, costYear,\n    serviceKw: shaftKw * SERVICE_FACTOR,\n    fillMin: s.roof ? s.roof.vol / Math.max(q, 1e-6) * 60 : 0,\n    Hsys, Ks, Kd, tempC: s.env.waterTempC, s,\n  };\n}\n"},"/assets/js/engine/water.js":{"type":"text/javascript; charset=utf-8","text":"// خصائص الماء والجو — معادلات تجريبية معروفة\nexport const G = 9.81;\n\n// الكثافة (كغ/م³) — Tanaka et al. 2001 (صيغة Thiesen المبسطة)\nexport function density(T) {\n  return 1000 * (1 - ((T + 288.9414) / (508929.2 * (T + 68.12963))) * (T - 3.9863) ** 2);\n}\n// اللزوجة الديناميكية (باسكال·ث) — Vogel\nexport function viscosity(T) {\n  return 2.414e-5 * 10 ** (247.8 / (T + 133.15));\n}\n// ضغط البخار (باسكال) — Buck 1981\nexport function vaporPressure(T) {\n  return 611.21 * Math.exp((18.678 - T / 234.5) * (T / (257.14 + T)));\n}\n// الضغط الجوي مع الارتفاع (باسكال) — الجو القياسي ISA\nexport function atmPressure(z) {\n  return 101325 * (1 - 2.25577e-5 * z) ** 5.25588;\n}\nexport function water(T) {\n  return { rho: density(T), mu: viscosity(T), pv: vaporPressure(T) };\n}\n"},"/assets/js/pages/admin.js":{"type":"text/javascript; charset=utf-8","text":"// لوحة الإدارة — تظهر فقط إذا أكّدت قاعدة البيانات أن المستخدم مدير\nimport { $, $$, el } from '../core/dom.js';\nimport { n0, date } from '../core/format.js';\nimport { auth, watchIdle, requireUser } from '../auth/index.js';\nimport { LOGO, toast, confirmButton } from '../ui/common.js';\n\n$$('[data-logo]').forEach(n => n.innerHTML = LOGO);\nconst ACTIONS = { login: 'دخول', logout: 'خروج', user_signedup: 'تسجيل', token_refreshed: 'تجديد', user_recovery_requested: 'طلب استعادة', user_updated_password: 'تغيير كلمة المرور', user_deleted: 'حذف مستخدم' };\nconst when = t => t ? date(t) + ' ' + new Date(t).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }) : '—';\n\nfunction table(node, heads, rows) {\n  node.replaceChildren(el('thead', {}, el('tr', {}, ...heads.map(h => el('th', { text: h })))), el('tbody', {}, ...rows));\n  if (!rows.length) node.querySelector('tbody').append(el('tr', {}, el('td', { colspan: heads.length, class: 'muted', text: 'لا توجد بيانات.' })));\n}\n\nasync function load() {\n  const o = await auth.rpc('admin_overview');\n  $('#stats').replaceChildren(...[['المستخدمون', o.users], ['نشطون آخر 7 أيام', o.active7], ['جدد آخر 7 أيام', o.new7], ['التصاميم', o.designs]]\n    .map(([k, v]) => el('div', {}, el('small', { text: k }), el('b', { class: 'num', text: n0(v) }))));\n  $('#signups').checked = !!o.signups_open;\n\n  const me = auth.user();\n  const users = await auth.rpc('admin_users');\n  table($('#users'), ['المستخدم', 'الدور', 'التسجيل', 'آخر دخول', 'التصاميم', ''], users.map(u => {\n    const role = el('select', { class: 'input', style: 'min-height:34px;width:auto', disabled: u.id === me.id },\n      el('option', { value: 'user', selected: u.role !== 'admin', text: 'مستخدم' }), el('option', { value: 'admin', selected: u.role === 'admin', text: 'مدير' }));\n    role.addEventListener('change', async () => { try { await auth.rpc('admin_set_role', { target: u.id, new_role: role.value }); toast('تم تغيير الدور'); } catch (e) { toast(e.message); load(); } });\n    const del = el('button', { class: 'btn sm quiet danger', text: 'حذف', disabled: u.id === me.id });\n    confirmButton(del, 'تأكيد الحذف', async () => { try { await auth.rpc('admin_delete_user', { target: u.id }); toast('حُذف المستخدم وتصاميمه'); load(); } catch (e) { toast(e.message); } });\n    return el('tr', {},\n      el('td', {}, el('b', { text: u.full_name || '—' }), el('div', { class: 'muted small num', text: u.email + (u.confirmed ? '' : ' · غير مفعّل') })),\n      el('td', {}, role), el('td', { class: 'num', text: when(u.created_at) }), el('td', { class: 'num', text: when(u.last_sign_in_at) }),\n      el('td', { class: 'n', text: n0(u.designs) }), el('td', {}, del));\n  }));\n\n  const log = await auth.rpc('admin_auth_log');\n  table($('#log'), ['الوقت', 'الحساب', 'العملية', 'IP'], log.filter(r => r.action !== 'token_refreshed').slice(0, 60)\n    .map(r => el('tr', {}, el('td', { class: 'num', text: when(r.at) }), el('td', { class: 'num', text: r.email || '—' }), el('td', { text: ACTIONS[r.action] || r.action || '—' }), el('td', { class: 'num', text: r.ip || '—' }))));\n\n  const ds = await auth.rpc('admin_designs');\n  table($('#designs'), ['التصميم', 'المالك', 'آخر تعديل'], ds.map(d => el('tr', {}, el('td', { text: d.name }), el('td', { class: 'num', text: d.owner_email }), el('td', { class: 'num', text: when(d.updated_at) }))));\n}\n\n$('#signups').addEventListener('change', async e => { try { await auth.rpc('admin_set_signups', { open: e.target.checked }); toast(e.target.checked ? 'التسجيل مفتوح' : 'التسجيل مغلق'); } catch (er) { toast(er.message); e.target.checked = !e.target.checked; } });\n$('#outBtn').addEventListener('click', async () => { await auth.signOut(); location.replace('index.html'); });\n\n(async () => {\n  const u = await requireUser(); if (!u) return;\n  if (!(await auth.isAdmin())) { location.replace('app.html'); return; }\n  watchIdle(async () => { await auth.signOut(); location.replace('index.html?m=' + encodeURIComponent('أُغلقت الجلسة بعد عدم النشاط.')); });\n  $('#wait').remove(); $('#admin').classList.remove('hidden');\n  try { await load(); } catch (e) { toast(e.message); }\n})();\n"},"/assets/js/pages/app.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// صفحة المصمم — تربط الحالة بالمشهد والمفتش والنوافذ\n// ═══════════════════════════════════════════════════════════════\nimport { $, el, reduceMotion } from '../core/dom.js';\nimport { n1, n2, n0, date } from '../core/format.js';\nimport { getState, getUI, subscribe, update, setUI, replace, fresh, isComplete } from '../core/store.js';\nimport { LIMITS } from '../core/sanitize.js';\nimport { auth, watchIdle, requireUser } from '../auth/index.js';\nimport { solve } from '../engine/solve.js';\nimport { demand } from '../engine/demand.js';\nimport { runChecks, verdict } from '../engine/checks.js';\nimport { requiredLengths, defaultPipes, fitToCurve } from '../engine/recommend.js';\nimport { BUILDINGS } from '../data/buildings.js';\nimport { byId } from '../data/pumps.js';\nimport { renderScene } from '../ui/scene.js';\nimport { renderInspector, readout } from '../ui/inspector.js';\nimport { buildingPicker, pumpPicker } from '../ui/pickers.js';\nimport { openAnalysis } from '../ui/analysis.js';\nimport { openSaved } from '../ui/saved.js';\nimport { toast, confirmButton, closeDialog, ICON, LOGO } from '../ui/common.js';\n\nlet currentId = null, R = null;\nconst GEOMETRY_KEYS = /^(building\\.|site|ground\\.depth|pump\\.)/;\n\n// ── أيقونات الأزرار والشعار ──\ndocument.querySelectorAll('[data-logo]').forEach(n => n.innerHTML = LOGO);\ndocument.querySelectorAll('[data-icon]').forEach(n => n.insertAdjacentHTML('afterbegin', ICON[n.dataset.icon] || ''));\n\n// ── الحساب ──\nconst compute = s => (isComplete(s) ? solve(s) : null);\n\nfunction autoLengths(s) {\n  if (!s.pump || !s.autoLength) return;\n  const L = requiredLengths(s, byId(s.pump.id).type);\n  s.suction.L = L.suction; s.discharge.L = L.discharge;\n  fitToCurve(s);\n}\n\nfunction setPump(id) {\n  update(s => {\n    const prevType = s.pump && byId(s.pump.id).type;\n    s.pump = { id, x: s.pump ? s.pump.x : Math.round(s.site * 0.35 * 2) / 2, z: s.pump ? s.pump.z : 0.3 };\n    if (!s.suction) Object.assign(s, defaultPipes(s, id));\n    if (!prevType || prevType !== byId(id).type || s.autoLength) {\n      const L = requiredLengths(s, byId(id).type); s.suction.L = L.suction; s.discharge.L = L.discharge; s.autoLength = true;\n    }\n    fitToCurve(s);\n  }, 'structure');\n  setUI({ selected: 'pump' }, 'select');\n}\n\n// ── الإجراءات من المشهد والمفتش ──\nconst actions = {\n  addBuilding: () => buildingPicker(type => {\n    const T = BUILDINGS[type];\n    update(s => { s.building = { type, floors: T.floors, floorH: T.floorH, perFloor: T.perFloor }; }, 'structure');\n    setUI({ selected: 'building' }, 'select');\n  }),\n  addRoof: () => { update(s => { s.roof = { vol: demand(s).roofRec }; }, 'structure'); setUI({ selected: 'roof' }, 'select'); },\n  addGround: () => { update(s => { s.ground = { vol: demand(s).groundRec, depth: 1.5 }; }, 'structure'); setUI({ selected: 'ground' }, 'select'); },\n  addPump: () => pumpPicker(getState(), null, setPump),\n  pickPump: () => pumpPicker(getState(), byId(getState().pump.id), setPump),\n  buildingType: t => { const T = BUILDINGS[t]; update(s => { Object.assign(s.building, { type: t, floorH: T.floorH, perFloor: T.perFloor }); autoLengths(s); }, 'structure'); },\n  autoLength: on => update(s => { s.autoLength = on; autoLengths(s); }, 'value'),\n};\nfunction select(what) { setUI({ selected: what }, 'select'); }\n\nfunction onChange(key, value) {\n  const [a, b] = LIMITS[key] || [-Infinity, Infinity];\n  update(s => {\n    const parts = key.split('.'); let o = s;\n    for (let i = 0; i \u003c parts.length - 1; i++) o = o[parts[i]];\n    o[parts.at(-1)] = typeof value === 'number' ? Math.min(b, Math.max(a, value)) : value;\n    if (key === 'site' && s.pump) s.pump.x = Math.min(s.pump.x, s.site - 0.5);\n    if (key.endsWith('.L') || key === 'discharge.valveK') s.autoLength = false;\n    else if (GEOMETRY_KEYS.test(key) || /\\.(d|mat|elbows)$|^env\\./.test(key)) autoLengths(s);\n  }, 'value');\n}\n\n// ── الرسم ──\nconst scene = $('#scene'), insp = $('#inspector');\nfunction paint(s, ui, why) {\n  R = compute(s);\n  scene.innerHTML = renderScene(s, ui, R);\n  if (why !== 'value' && why !== 'fill') renderInspector(insp, s, ui, R, { onChange, onAction: (k, v) => actions[k](v) });\n  else if (R) { const ro = $('#readout'); if (ro) ro.replaceWith(readout(R)); }\n  paintStatus(s, ui);\n  paintTitle(s);\n  $('#run').disabled = !R; $('#analyze').disabled = !R;\n  $('#run').querySelector('span').textContent = ui.running ? 'إيقاف' : 'تشغيل';\n}\nfunction paintStatus(s, ui) {\n  const lamp = $('#lamp'), msg = $('#statusMsg');\n  let k = '', m = !s.building ? 'ابدأ بإضافة المبنى من المربع المنقّط.' : !s.roof ? 'أضف الخزان العلوي فوق السطح.' : !s.ground ? 'أضف الخزان الأرضي.' : 'أضف المضخة لتوصيل الخزانين.';\n  if (R) {\n    if (ui.running) {\n      if (R.noLift) { k = 'bad'; m = 'المحرك يدور والماء لا يصعد: ضاغط المضخة أقل من الرفع.'; }\n      else if (R.air) { k = 'bad'; m = 'فقاعات هواء — ماسورة السحب لا تصل إلى سطح الماء.'; }\n      else if (R.leak) { k = 'bad'; m = 'تسرّب — ماسورة الدفع لا تصل إلى الخزان العلوي.'; }\n      else if (R.cavitation) { k = 'bad'; m = 'تكهف — صوت حصى داخل المضخة، NPSH المتاح أقل من المطلوب.'; }\n      else { k = 'ok'; m = `يضخ ${n2(R.q)} م³/س عند ${n1(R.h)} م — يمتلئ الخزان العلوي في ${n0(R.fillMin)} دقيقة.`; }\n    } else {\n      const v = verdict(runChecks(R, s)); k = v.level;\n      m = v.bad ? `مشكلات حرجة: ${v.bad} — افتح المذكرة الحسابية لإصلاحها.` : v.warn ? `يعمل، مع ملاحظات: ${v.warn}.` : `التصميم سليم — ${n2(R.q)} م³/س عند ${n1(R.h)} م.`;\n    }\n  }\n  lamp.className = 'lamp ' + k; msg.textContent = m;\n}\nfunction paintTitle(s) {\n  $('#tbProject').textContent = s.name || 'بدون اسم';\n  $('#tbBuilding').textContent = s.building ? `${BUILDINGS[s.building.type].name} · ${s.building.floors} أدوار` : '—';\n  $('#tbPump').textContent = s.pump ? byId(s.pump.id).model : '—';\n  $('#tbDate').textContent = date(Date.now());\n}\nsubscribe(paint);\n\n// ── أحداث المشهد ──\nscene.addEventListener('click', e => { const t = e.target.closest('[data-act]'); if (!t) return; const a = t.dataset.act; actions[a] ? actions[a]() : select(a); });\nscene.addEventListener('keydown', e => { if (e.key !== 'Enter' && e.key !== ' ') return; const t = e.target.closest('[data-act]'); if (!t) return; e.preventDefault(); const a = t.dataset.act; actions[a] ? actions[a]() : select(a); });\n\n// ── التشغيل ──\nlet last = 0;\nfunction loop(ts) {\n  const ui = getUI(); if (!ui.running) return;\n  const dt = last ? (ts - last) / 1000 : 0; last = ts;\n  if (R && R.flows) {\n    const span = Math.min(24, Math.max(5, R.fillMin / 6));\n    ui.fill = Math.min(1, ui.fill + dt / span);\n    const w = document.getElementById('roofWater');\n    if (w) { const bottom = +w.getAttribute('y') + +w.getAttribute('height'), lv = 50 * ui.fill; w.setAttribute('y', bottom - lv); w.setAttribute('height', lv); }\n    if (ui.fill >= 1) { setUI({ running: false, fill: 1 }, 'fill'); toast('امتلأ الخزان العلوي — العوّامة فصلت المضخة.'); return; }\n  }\n  requestAnimationFrame(loop);\n}\n$('#run').addEventListener('click', () => {\n  const ui = getUI();\n  if (!ui.running && ui.fill >= 0.98) ui.fill = 0.15;\n  setUI({ running: !ui.running }, 'fill');\n  if (getUI().running) { last = 0; requestAnimationFrame(loop); }\n});\nif (reduceMotion()) document.documentElement.classList.add('reduce');\n\n// ── الأزرار العلوية ──\n$('#analyze').addEventListener('click', () => {\n  const open = () => openAnalysis(getState(), R, { canPrint: auth.name !== 'claude', onFix: f => { update(s => f.apply(s), 'structure'); closeDialog(); toast('طُبّق الإصلاح'); open(); } });\n  if (R) open();\n});\n$('#envBtn').addEventListener('click', () => select('env'));\n$('#savedBtn').addEventListener('click', () => openSaved(getState, { currentId, onOpen: (d, id) => { currentId = id; replace(d); }, onSaved: id => { currentId = id; paintTitle(getState()); } }));\nconfirmButton($('#newBtn'), 'تأكيد المسح؟', () => { currentId = null; replace(fresh()); });\n$('#projName').addEventListener('input', e => { update(s => { s.name = e.target.value.slice(0, 60); }, 'value'); });\n$('#outBtn').addEventListener('click', () => signOut('تم تسجيل الخروج.'));\n\nasync function signOut(msg) {\n  await auth.signOut();\n  if (auth.name === 'claude') { replace(fresh()); $('#app').classList.add('hidden'); $('#gate').classList.remove('hidden'); $('#gateMsg').textContent = msg; }\n  else location.replace('index.html?m=' + encodeURIComponent(msg));\n}\n\n// ── الدخول ──\nasync function start(user) {\n  $('#uname').textContent = user.name;\n  $('#gate')?.classList.add('hidden'); $('#app').classList.remove('hidden');\n  const admin = await auth.isAdmin(); $('#adminLink')?.classList.toggle('hidden', !admin);\n  watchIdle(() => signOut('أُغلقت الجلسة تلقائياً بعد فترة دون نشاط.'));\n  replace(fresh());\n}\nif (auth.name === 'claude') {\n  $('#gate').classList.remove('hidden');\n  $('#gateBtn').addEventListener('click', async () => {\n    const b = $('#gateBtn'); b.disabled = true; $('#gateMsg').textContent = 'جارٍ التحقق من هويتك…';\n    try { start(await auth.signIn()); } catch (e) { $('#gateMsg').textContent = e.message; } finally { b.disabled = false; }\n  });\n} else {\n  requireUser().then(u => u && start(u));\n}\n"},"/assets/js/pages/catalog.js":{"type":"text/javascript; charset=utf-8","text":"// صفحة الكتالوج: تعرض PUMPS و SOURCES من data/pumps.js كما هي\nimport { $, $$, el } from '../core/dom.js';\nimport { n1, n2 } from '../core/format.js';\nimport { PUMPS, PUMP_TYPES, SOURCES } from '../data/pumps.js';\nimport { LOGO } from '../ui/common.js';\nimport { sparkline } from '../ui/chart.js';\n\n$$('[data-logo]').forEach(n => n.innerHTML = LOGO);\nconst list = $('#list'), toc = $('#toc');\n\nfor (const [type, T] of Object.entries(PUMP_TYPES)) {\n  const pumps = PUMPS.filter(p => p.type === type), src = SOURCES[pumps[0].src];\n  toc.append(el('a', { href: '#t-' + type, text: T.name }));\n  const sec = el('section', { class: 'cat-sec', id: 't-' + type },\n    el('h2', { text: T.name }), el('p', { class: 'muted', text: T.note }),\n    el('div', { class: 'src' },\n      el('div', {}, el('small', { text: 'المصدر' }), el('a', { href: src.url, target: '_blank', rel: 'noopener noreferrer', text: src.title })),\n      el('div', {}, el('small', { text: 'الناشر' }), el('span', { text: src.publisher })),\n      el('div', {}, el('small', { text: 'التردد / السرعة' }), el('span', { class: 'num', text: `${src.hz} Hz · ${src.rpm} rpm` })),\n      el('p', { class: 'small muted', text: src.notes })));\n  for (const p of pumps) {\n    const qs = p.curve.map(c => c[0]);\n    const tbl = el('table', { class: 'table' },\n      el('thead', {}, el('tr', {}, el('th', { text: 'Q لتر/دقيقة' }), ...qs.map(q => el('th', { class: 'n', text: String(q) })))),\n      el('tbody', {},\n        el('tr', {}, el('td', { class: 'muted', text: 'Q م³/س' }), ...qs.map(q => el('td', { class: 'n', text: n2(q * 0.06) }))),\n        el('tr', {}, el('td', { text: 'H متر' }), ...p.curve.map(c => el('td', { class: 'n', text: n1(c[1]) })))));\n    const card = el('article', { class: 'pump-card', id: p.id },\n      el('header', {}, el('div', {}, el('h3', { text: p.model }), el('span', { class: 'muted small', text: `${p.kw} ك.واط · منافذ ${p.ports}${p.stages ? ' · ' + p.stages + ' مراحل' : ''} · حرارة حتى ${p.tMax}°م${p.maxLift ? ' · سحب حتى ' + p.maxLift + ' م' : ''}${p.maxBar ? ' · جسم ' + p.maxBar + ' بار' : ''}` })), el('span', { class: 'spark' })),\n      el('div', { class: 'scroll-x' }, tbl));\n    card.querySelector('.spark').innerHTML = sparkline(p, 120, 40);\n    sec.append(card);\n  }\n  list.append(sec);\n}\nif (location.hash) document.getElementById(location.hash.slice(1))?.scrollIntoView();\n"},"/assets/js/pages/login.js":{"type":"text/javascript; charset=utf-8","text":"// صفحة الدخول والتسجيل + رسم المثال الحي\nimport { $, $$ } from '../core/dom.js';\nimport { auth } from '../auth/index.js';\nimport { LOGO } from '../ui/common.js';\nimport { renderScene } from '../ui/scene.js';\nimport { solve } from '../engine/solve.js';\nimport { fresh } from '../core/store.js';\nimport { requiredLengths, defaultPipes } from '../engine/recommend.js';\n\n$$('[data-logo]').forEach(n => n.innerHTML = LOGO);\n\n// مثال حي في الواجهة: بيت من دورين بمضخة CPm 610\n(function hero() {\n  const s = fresh();\n  s.building = { type: 'house', floors: 2, floorH: 3.2, perFloor: 5 };\n  s.roof = { vol: 1 }; s.ground = { vol: 2, depth: 1.5 };\n  s.pump = { id: 'cpm610', x: 3.5, z: 0.3 };\n  Object.assign(s, defaultPipes(s, 'cpm610'));\n  const L = requiredLengths(s, 'surface'); s.suction.L = L.suction; s.discharge.L = L.discharge;\n  $('#hero').innerHTML = renderScene(s, { selected: null, running: true, fill: 0.55 }, solve(s));\n  $('#hero').querySelectorAll('[tabindex]').forEach(n => n.removeAttribute('tabindex'));\n})();\n\nconst msg = (t, k = '') => { const m = $('#msg'); m.textContent = t; m.className = 'msg ' + k; };\nconst q = new URLSearchParams(location.search).get('m');\nif (q) msg(q.slice(0, 120), 'ok');\n\nif (!auth.configured()) msg('الموقع لم يُربط بقاعدة البيانات بعد: أضف supabaseUrl وsupabaseKey في assets/js/config.js.', 'bad');\nelse auth.init().then(u => { if (u) location.replace('app.html'); });\n\n// التبويبات\n$$('[data-tab]').forEach(b => b.addEventListener('click', () => {\n  $$('[data-tab]').forEach(x => x.setAttribute('aria-selected', String(x === b)));\n  $('#fIn').classList.toggle('hidden', b.dataset.tab !== 'in');\n  $('#fUp').classList.toggle('hidden', b.dataset.tab !== 'up');\n  msg('');\n}));\n\nconst emailOk = v => /^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(v);\nconst strength = p => (p.length >= 10) + (/[a-z]/i.test(p)) + (/\\d/.test(p)) + (/[^a-z0-9]/i.test(p)) + (p.length >= 14);\n\n$('#upPass').addEventListener('input', e => {\n  const n = strength(e.target.value), i = $('#meter');\n  i.style.width = (n * 20) + '%'; i.style.background = n >= 4 ? 'var(--ok)' : n >= 3 ? 'var(--warn)' : 'var(--fault)';\n});\n\n// قفل بسيط بعد محاولات فاشلة متتالية (الحماية الأساسية في الخادم)\nlet fails = 0, lockUntil = 0;\nasync function guarded(form, fn) {\n  if (Date.now() \u003c lockUntil) { msg(`انتظر ${Math.ceil((lockUntil - Date.now()) / 1000)} ثانية ثم أعد المحاولة.`, 'bad'); return; }\n  const btn = form.querySelector('[type=submit]'); btn.disabled = true;\n  try { await fn(); fails = 0; }\n  catch (e) { fails++; if (fails >= 5) { lockUntil = Date.now() + 60e3 * Math.min(10, fails - 4); } msg(e.message || 'تعذّر الطلب.', 'bad'); }\n  finally { btn.disabled = false; }\n}\n\n$('#fIn').addEventListener('submit', e => {\n  e.preventDefault();\n  const email = $('#inEmail').value.trim(), pass = $('#inPass').value;\n  if (!emailOk(email) || !pass) { msg('أدخل بريداً صحيحاً وكلمة المرور.', 'bad'); return; }\n  guarded(e.target, async () => { msg('جارٍ الدخول…'); await auth.signIn(email, pass); location.replace('app.html'); });\n});\n\n$('#fUp').addEventListener('submit', e => {\n  e.preventDefault();\n  const name = $('#upName').value.replace(/[\u003c>\\u0000-\\u001f]/g, '').trim().slice(0, 60), email = $('#upEmail').value.trim(), pass = $('#upPass').value;\n  if (!name) { msg('اكتب اسمك.', 'bad'); return; }\n  if (!emailOk(email)) { msg('البريد غير صحيح.', 'bad'); return; }\n  if (strength(pass) \u003c 3 || pass.length \u003c 10) { msg('كلمة المرور ضعيفة: 10 أحرف على الأقل وتشمل حروفاً وأرقاماً.', 'bad'); return; }\n  guarded(e.target, async () => {\n    const r = await auth.signUp(email, pass, name);\n    if (r.confirm) msg('أرسلنا رابط تفعيل إلى بريدك. فعّل الحساب ثم سجّل الدخول.', 'ok');\n    else location.replace('app.html');\n  });\n});\n\n$('#forgot').addEventListener('click', async () => {\n  const email = $('#inEmail').value.trim();\n  if (!emailOk(email)) { msg('اكتب بريدك في الحقل أولاً.', 'bad'); return; }\n  try { await auth.resetPassword(email); } catch {}\n  msg('إن كان البريد مسجّلاً فستصلك رسالة لإعادة تعيين كلمة المرور.', 'ok'); // نفس الرد دائماً لمنع كشف الحسابات\n});\n"},"/assets/js/pages/reset.js":{"type":"text/javascript; charset=utf-8","text":"// تعيين كلمة مرور جديدة من رابط البريد\nimport { $, $$ } from '../core/dom.js';\nimport { supabaseAuth } from '../auth/supabase.js';\nimport { LOGO } from '../ui/common.js';\n\n$$('[data-logo]').forEach(n => n.innerHTML = LOGO);\nconst params = new URLSearchParams(location.hash.slice(1));\nconst token = params.get('type') === 'recovery' ? params.get('access_token') : null;\nhistory.replaceState(null, '', location.pathname); // إزالة الرمز من شريط العنوان والسجل\nconst msg = (t, k = '') => { const m = $('#msg'); m.textContent = t; m.className = 'msg ' + k; };\nif (!token) msg('الرابط غير صالح أو انتهت صلاحيته. اطلب رابطاً جديداً من صفحة الدخول.', 'bad');\n\n$('#f').addEventListener('submit', async e => {\n  e.preventDefault();\n  const a = $('#p1').value, b = $('#p2').value;\n  if (!token) return;\n  if (a.length \u003c 10 || !/[a-z]/i.test(a) || !/\\d/.test(a)) { msg('كلمة المرور ضعيفة.', 'bad'); return; }\n  if (a !== b) { msg('الكلمتان غير متطابقتين.', 'bad'); return; }\n  try { await supabaseAuth.setPasswordWithToken(token, a); location.replace('index.html?m=' + encodeURIComponent('تم تغيير كلمة المرور. سجّل الدخول.')); }\n  catch (er) { msg(er.message, 'bad'); }\n});\n"},"/assets/js/storage/designs.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// حفظ التصاميم — نفس الواجهة للمزوّدين:\n// list() → [{id, name, updated}]   load(id) → object   save(name, data, id?) → id   remove(id)\n// ═══════════════════════════════════════════════════════════════\nimport { auth } from '../auth/index.js';\n\nconst MAX = 60;\nconst clip = s => String(s || '').replace(/[\\u0000-\\u001f\u003c>]/g, '').trim().slice(0, MAX) || 'تصميم بدون اسم';\n\nconst supa = {\n  async list() {\n    const rows = await auth.rest('/rest/v1/designs?select=id,name,updated_at&order=updated_at.desc&limit=100');\n    return (rows || []).map(r => ({ id: r.id, name: r.name, updated: Date.parse(r.updated_at) }));\n  },\n  async load(id) {\n    const rows = await auth.rest('/rest/v1/designs?select=data&id=eq.' + encodeURIComponent(id));\n    return rows?.[0]?.data ?? null;\n  },\n  async save(name, data, id) {\n    if (id) {\n      await auth.rest('/rest/v1/designs?id=eq.' + encodeURIComponent(id), { method: 'PATCH', body: { name: clip(name), data } });\n      return id;\n    }\n    const r = await auth.rest('/rest/v1/designs', { method: 'POST', body: { name: clip(name), data }, prefer: 'return=representation' });\n    return r?.[0]?.id;\n  },\n  async remove(id) { await auth.rest('/rest/v1/designs?id=eq.' + encodeURIComponent(id), { method: 'DELETE' }); },\n};\n\nconst claude = {\n  coll() { const db = auth.db(), u = auth.user(); if (!db || !u) throw new Error('الحفظ غير متاح في هذا العرض.'); return db.collection('data/users/' + u.id); },\n  async list() {\n    const q = await this.coll().orderBy('at', 'desc').limit(100).get();\n    return q.docs.map(d => { const v = d.data() || {}; return { id: d.id, name: String(v.name || ''), updated: Number(v.at) || 0 }; });\n  },\n  async load(id) { const d = await this.coll().doc(id).get(); if (!d.exists) return null; try { return JSON.parse(String(d.data().st || '')); } catch { return null; } },\n  async save(name, data, id) {\n    id = id || 'd' + Date.now().toString(36);\n    await this.coll().doc(id).set({ name: clip(name), at: Date.now(), st: JSON.stringify(data) });\n    return id;\n  },\n  async remove(id) { await this.coll().doc(id).delete(); },\n};\n\nexport const designs = auth.name === 'claude' ? claude : supa;\n"},"/assets/js/ui/analysis.js":{"type":"text/javascript; charset=utf-8","text":"// المذكرة الحسابية: الحكم، المؤشرات، المنحنى، الفحوصات، التفاصيل\nimport { el } from '../core/dom.js';\nimport { n0, n1, n2 } from '../core/format.js';\nimport { openDialog, toast, ICON } from './common.js';\nimport { runChecks, verdict } from '../engine/checks.js';\nimport { curveChart } from './chart.js';\nimport { BUILDINGS } from '../data/buildings.js';\nimport { MATERIALS } from '../data/materials.js';\nimport { PUMP_TYPES, SOURCES } from '../data/pumps.js';\n\nconst LEVEL = { ok: 'سليم', warn: 'ملاحظة', bad: 'حرج', info: 'معلومة' };\n\nfunction sec(no, title, sub, ...kids) {\n  return el('section', { class: 'memo-sec' }, el('h3', {}, document.createTextNode(no + '. ' + title), sub ? el('span', { text: sub }) : null), ...kids);\n}\nfunction kpis(items) {\n  return el('div', { class: 'kpi-grid' }, ...items.map(([k, v, u]) => el('div', {}, el('small', { text: k }), el('b', { class: 'num', text: v }), u ? el('i', { text: u }) : null)));\n}\n\nexport function reportText(s, R) {\n  const list = runChecks(R, s);\n  return [`pump.zeen — مذكرة حسابية`, `المبنى: ${BUILDINGS[s.building.type].name}، ${s.building.floors} أدوار، الطلب ${n1(R.D.daily)} م³/يوم`,\n    `المضخة: ${R.pump.model} (${PUMP_TYPES[R.pump.type].name}، ${R.pump.kw} ك.واط) — ${SOURCES[R.pump.src].title}`,\n    `السحب: L=${s.suction.L} م، Ø${s.suction.d} مم، ${MATERIALS[s.suction.mat].name} | الدفع: L=${s.discharge.L} م، Ø${s.discharge.d} مم، ${MATERIALS[s.discharge.mat].name}`,\n    `نقطة التشغيل: Q=${n2(R.q)} م³/س، H=${n1(R.h)} م، Hs=${n2(R.g.Hs)} م`, '',\n    ...list.map(c => `[${LEVEL[c.level]}] ${c.title}: ${c.detail}`)].join('\\n');\n}\n\nexport function openAnalysis(s, R, { onFix, canPrint }) {\n  const list = runChecks(R, s), v = verdict(list);\n  const head = {\n    bad: ['التصميم لن يعمل كما يجب', `مشكلات حرجة: ${v.bad}. ابدأ من أعلى الجدول؛ لكل مشكلة زر إصلاح.`],\n    warn: ['يعمل، مع ملاحظات', `ملاحظات: ${v.warn}. تحسّن العمر والكفاءة.`],\n    ok: ['تصميم سليم', 'كل الفحوصات ضمن الحدود الهندسية.'],\n  }[v.level];\n\n  const rows = list.map(c => {\n    const td = el('td', {}, el('b', { text: c.title }), el('p', { text: c.detail }));\n    if (c.fixes.length) td.append(el('div', { class: 'fixes no-print' }, ...c.fixes.map(f => el('button', { class: 'btn sm', text: f.label, onclick: () => onFix(f) }))));\n    return el('tr', {}, el('td', {}, el('span', { class: 'tag ' + c.level, text: LEVEL[c.level] })), td);\n  });\n\n  const chart = el('div', { class: 'chart' }); chart.innerHTML = curveChart(R);\n  const src = SOURCES[R.pump.src];\n\n  const body = el('div', {},\n    el('div', { class: 'verdict ' + v.level }, el('span', { class: 'lamp ' + v.level }), el('b', { text: head[0] }), el('p', { text: head[1] })),\n    sec(1, 'نقطة التشغيل', R.pump.model, kpis([\n      ['التدفق Q', n2(R.q), 'م³/س'], ['الضاغط الكلي H', n1(R.h), 'م'], ['الرفع الساكن Hs', n2(R.g.Hs), 'م'], ['الكفاءة ≈', n0(R.eta * 100) + '%', 'تقديري'],\n      ['قدرة العمود ≈', n2(R.shaftKw), 'ك.واط'], ['هامش NPSH', R.sub ? '—' : n2(R.margin), R.sub ? 'غاطسة' : 'م'],\n      ['ملء الخزان العلوي', R.flows ? n0(R.fillMin) : '—', 'دقيقة'], ['تشغيل يومي', Number.isFinite(R.runH) ? n1(R.runH) : '—', 'ساعة'],\n      ['كهرباء سنوياً ≈', Number.isFinite(R.runH) ? n0(R.costYear) : '—', 'ريال'], ['أقصى ضغط', n1(R.pMaxBar), 'بار'],\n    ])),\n    sec(2, 'منحنى المضخة والنظام', 'تقاطعهما = نقطة التشغيل', chart),\n    sec(3, 'الفحوصات', `${list.length} بنداً`, el('div', { class: 'scroll-x' }, el('table', { class: 'table checks' }, el('tbody', {}, ...rows)))),\n    sec(4, 'تفاصيل الحساب', 'Darcy–Weisbach · Swamee–Jain · Joukowsky', kpis([\n      ['فقد الدفع: احتكاك + موضعي', n2(R.L.d.hf) + ' + ' + n2(R.L.d.hm), 'م'],\n      ...(R.L.s ? [['فقد السحب: احتكاك + موضعي', n2(R.L.s.hf) + ' + ' + n2(R.L.s.hm), 'م']] : []),\n      ['رينولدز (الدفع)', n0(R.L.d.Re), 'f = ' + R.L.d.f.toFixed(4)], ['ΣK سحب / دفع', (R.sub ? '—' : n1(R.Ks)) + ' / ' + n1(R.Kd)],\n      ['كثافة الماء', n1(R.w.rho), 'كغ/م³'], ['ضغط البخار', n2(R.w.pv / 1000), 'ك.باسكال'], ['الضغط الجوي', n1(R.pa / 1000), 'ك.باسكال'],\n      ['ارتفاع الطرق المائي', n1(R.surge), 'م'], ['تدفق BEP التقديري', n2(R.C.qBep), 'م³/س'], ['قدرة محرك الخدمة ≥', n2(R.serviceKw), 'ك.واط'],\n    ])),\n    sec(5, 'المراجع', '', el('p', { class: 'small muted' },\n      el('span', { text: 'منحنى المضخة: ' }), el('a', { href: src.url, target: '_blank', rel: 'noopener noreferrer', text: src.title }),\n      el('span', { text: ` (${src.hz} Hz، ${src.rpm} rpm). ${src.notes} الكفاءة وNPSHr تقديريتان لأن الكتالوج لا ينشرهما لهذه الموديلات؛ راجع منحنيات المورد قبل الشراء.` }))),\n    el('div', { class: 'no-print', style: 'display:flex;gap:10px;flex-wrap:wrap;margin-top:22px' },\n      (() => { const b = el('button', { class: 'btn' }); b.innerHTML = ICON.copy + '\u003cspan>نسخ الملخص\u003c/span>'; b.onclick = () => navigator.clipboard.writeText(reportText(s, R)).then(() => toast('نُسخ الملخص'), () => toast('تعذّر النسخ')); return b; })(),\n      canPrint ? (() => { const b = el('button', { class: 'btn' }); b.innerHTML = ICON.print + '\u003cspan>طباعة / PDF\u003c/span>'; b.onclick = () => print(); return b; })() : null));\n\n  openDialog({ title: 'المذكرة الحسابية', sub: `${R.pump.model} · ${PUMP_TYPES[R.pump.type].name} · ماء ${n0(s.env.waterTempC)}°م · ارتفاع ${n0(s.env.altitudeM)} م`, body, wide: true });\n}\n"},"/assets/js/ui/chart.js":{"type":"text/javascript; charset=utf-8","text":"// منحنى المضخة ومنحنى النظام — SVG بمقاسه الحقيقي\nimport { n0, n1 } from '../core/format.js';\n\nexport function curveChart(R, width = 640, height = 320) {\n  const l = 46, r = 14, t = 26, b = 40, C = R.C;\n  const qM = C.qMax * 1.08, hM = Math.max(C.H0, R.Hsys(C.qMax)) * 1.1;\n  const X = q => l + q / qM * (width - l - r), Y = h => height - b - h / hM * (height - t - b);\n  const ticks = n => Array.from({ length: n + 1 }, (_, i) => i / n);\n  let o = `\u003csvg viewBox=\"0 0 ${width} ${height}\" direction=\"ltr\" role=\"img\" aria-label=\"منحنى المضخة ومنحنى النظام\">\u003cdefs>\u003cclipPath id=\"cc\">\u003crect x=\"${l}\" y=\"${t}\" width=\"${width - l - r}\" height=\"${height - t - b}\"/>\u003c/clipPath>\u003c/defs>`;\n  for (const k of ticks(5)) { const y = Y(hM * k); o += `\u003cline x1=\"${l}\" x2=\"${width - r}\" y1=\"${y}\" y2=\"${y}\" stroke=\"var(--rule-soft)\"/>\u003ctext x=\"${l - 6}\" y=\"${y + 4}\" font-size=\"11\" text-anchor=\"end\" fill=\"var(--ink-3)\">${n0(hM * k)}\u003c/text>`; }\n  for (const k of ticks(6)) { const x = X(qM * k); o += `\u003cline x1=\"${x}\" x2=\"${x}\" y1=\"${t}\" y2=\"${height - b}\" stroke=\"var(--rule-soft)\"/>\u003ctext x=\"${x}\" y=\"${height - b + 16}\" font-size=\"11\" text-anchor=\"middle\" fill=\"var(--ink-3)\">${n1(qM * k)}\u003c/text>`; }\n  o += `\u003cline x1=\"${l}\" x2=\"${width - r}\" y1=\"${height - b}\" y2=\"${height - b}\" stroke=\"var(--ink)\"/>\u003cline x1=\"${l}\" x2=\"${l}\" y1=\"${t}\" y2=\"${height - b}\" stroke=\"var(--ink)\"/>`;\n  o += `\u003ctext x=\"${(l + width - r) / 2}\" y=\"${height - 6}\" font-size=\"12\" text-anchor=\"middle\" fill=\"var(--ink-2)\">Q (m³/h)\u003c/text>\u003ctext x=\"${l}\" y=\"14\" font-size=\"12\" fill=\"var(--ink-2)\">H (m)\u003c/text>`;\n  const pc = [], sc = [];\n  for (let i = 0; i \u003c= 60; i++) { const q = C.qMax * i / 60; pc.push([X(q), Y(C.H(q))]); }\n  for (let i = 0; i \u003c= 60; i++) { const q = qM * i / 60; sc.push([X(q), Y(R.Hsys(q))]); }\n  const P = a => 'M' + a.map(p => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join('L');\n  o += `\u003cg clip-path=\"url(#cc)\">\u003cpath d=\"${P(sc)}\" fill=\"none\" stroke=\"var(--fault)\" stroke-width=\"2\"/>\u003cpath d=\"${P(pc)}\" fill=\"none\" stroke=\"var(--water)\" stroke-width=\"2.4\"/>\u003c/g>`;\n  o += C.pts.map(([q, h]) => `\u003ccircle cx=\"${X(q)}\" cy=\"${Y(h)}\" r=\"2.6\" fill=\"var(--sheet)\" stroke=\"var(--water)\" stroke-width=\"1.4\"/>`).join('');\n  o += `\u003cline x1=\"${X(R.D.qReq)}\" x2=\"${X(R.D.qReq)}\" y1=\"${t}\" y2=\"${height - b}\" stroke=\"var(--ink-2)\" stroke-dasharray=\"4 4\"/>`;\n  o += `\u003cpath d=\"M${X(C.qBep)} ${Y(C.H(C.qBep)) - 7}l6 7-6 7-6-7z\" fill=\"var(--ok)\"/>`;\n  if (!R.noLift) o += `\u003ccircle cx=\"${X(R.q)}\" cy=\"${Y(R.h)}\" r=\"7\" fill=\"var(--sheet)\" stroke=\"var(--ink)\" stroke-width=\"2.4\"/>`;\n  o += `\u003c/svg>`;\n  return o + `\u003cdiv class=\"legend\">\u003cspan>\u003ci style=\"--c:var(--water)\">\u003c/i>منحنى المضخة (نقاط الكتالوج)\u003c/span>\u003cspan>\u003ci style=\"--c:var(--fault)\">\u003c/i>منحنى النظام\u003c/span>\u003cspan>\u003ci class=\"dash\" style=\"--c:var(--ink-2)\">\u003c/i>التدفق المطلوب\u003c/span>\u003cspan>◆ BEP تقديري\u003c/span>\u003cspan>● نقطة التشغيل\u003c/span>\u003c/div>`;\n}\n\n// منحنى مصغر لجدول المضخات\nexport function sparkline(pump, w = 90, h = 32) {\n  const pts = pump.curve, qM = pts[pts.length - 1][0], hM = pts[0][1];\n  const d = 'M' + pts.map(([q, hh]) => `${(2 + q / qM * (w - 4)).toFixed(1)},${(h - 2 - hh / hM * (h - 6)).toFixed(1)}`).join('L');\n  return `\u003csvg viewBox=\"0 0 ${w} ${h}\" direction=\"ltr\" aria-hidden=\"true\">\u003cpath d=\"${d}\" fill=\"none\" stroke=\"var(--water)\" stroke-width=\"1.6\"/>\u003c/svg>`;\n}\n"},"/assets/js/ui/common.js":{"type":"text/javascript; charset=utf-8","text":"// نوافذ، تنبيهات، أيقونات، الشعار\nimport { $, el } from '../core/dom.js';\n\nlet lastFocus = null;\nexport function openDialog({ title, sub = '', body, wide = false, onClose }) {\n  closeDialog();\n  lastFocus = document.activeElement;\n  const head = el('div', { class: 'dialog-head' },\n    el('div', {}, el('h2', { text: title }), sub ? el('p', { text: sub }) : null),\n    el('button', { class: 'x-btn', 'aria-label': 'إغلاق', onclick: closeDialog, text: '×' }));\n  const box = el('div', { class: 'dialog', role: 'dialog', 'aria-modal': 'true', 'aria-label': title, style: wide ? 'width:min(1040px,100%)' : '' }, head, el('div', { class: 'dialog-body' }, body));\n  const ov = el('div', { class: 'overlay', id: 'overlay', onclick: e => { if (e.target === ov) closeDialog(); } }, box);\n  ov._onClose = onClose;\n  document.body.append(ov);\n  box.querySelector('button')?.focus();\n  return box;\n}\nexport function closeDialog() {\n  const ov = $('#overlay'); if (!ov) return;\n  ov._onClose?.(); ov.remove(); lastFocus?.focus?.();\n}\naddEventListener('keydown', e => { if (e.key === 'Escape') closeDialog(); });\n\nlet tt;\nexport function toast(msg) {\n  let t = $('#toast');\n  if (!t) { t = el('div', { id: 'toast', role: 'status' }); document.body.append(t); }\n  t.textContent = msg; t.classList.remove('hidden');\n  clearTimeout(tt); tt = setTimeout(() => t.classList.add('hidden'), 3200);\n}\n\n// زر بتأكيد بضغطة ثانية (بديل confirm الممنوع في بعض البيئات)\nexport function confirmButton(btn, label, run) {\n  const orig = btn.textContent;\n  btn.addEventListener('click', async () => {\n    if (btn.dataset.armed !== '1') { btn.dataset.armed = '1'; btn.textContent = label; setTimeout(() => { btn.dataset.armed = ''; btn.textContent = orig; }, 3000); return; }\n    btn.dataset.armed = ''; btn.textContent = orig; await run();\n  });\n}\n\nconst svg = d => `\u003csvg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">${d}\u003c/svg>`;\nexport const ICON = {\n  play: svg('\u003cpath d=\"M7 5v14l12-7z\"/>'),\n  stop: svg('\u003crect x=\"6\" y=\"6\" width=\"12\" height=\"12\"/>'),\n  doc: svg('\u003cpath d=\"M6 3h9l4 4v14H6z\"/>\u003cpath d=\"M14 3v5h5M9 13h7M9 17h5\"/>'),\n  folder: svg('\u003cpath d=\"M3 6h7l2 2h9v11H3z\"/>'),\n  save: svg('\u003cpath d=\"M5 3h12l3 3v15H5z\"/>\u003cpath d=\"M8 3v6h8V3M8 21v-7h8v7\"/>'),\n  out: svg('\u003cpath d=\"M10 4H5v16h5M15 8l4 4-4 4M19 12H9\"/>'),\n  gear: svg('\u003ccircle cx=\"12\" cy=\"12\" r=\"3\"/>\u003cpath d=\"M12 2v3M12 19v3M4.2 4.2l2.1 2.1M17.7 17.7l2.1 2.1M2 12h3M19 12h3M4.2 19.8l2.1-2.1M17.7 6.3l2.1-2.1\"/>'),\n  book: svg('\u003cpath d=\"M4 4h7a3 3 0 0 1 3 3v13a2 2 0 0 0-2-2H4zM20 4h-6M20 4v14h-6\"/>'),\n  plus: svg('\u003cpath d=\"M12 5v14M5 12h14\"/>'),\n  print: svg('\u003cpath d=\"M7 8V3h10v5M7 17H4V9h16v8h-3M7 14h10v7H7z\"/>'),\n  copy: svg('\u003crect x=\"8\" y=\"8\" width=\"12\" height=\"12\"/>\u003cpath d=\"M16 8V4H4v12h4\"/>'),\n  shield: svg('\u003cpath d=\"M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z\"/>'),\n};\n\n// الشعار: دوّار مضخة بست ريش داخل حلزون\nexport const LOGO = `\u003csvg viewBox=\"0 0 32 32\" aria-hidden=\"true\">\u003cpath d=\"M16 3a13 13 0 1 0 13 13h-4a9 9 0 1 1-9-9z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\"/>\u003cpath d=\"M25 16h4V3h-4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linejoin=\"round\"/>\u003cg fill=\"currentColor\">${[0,60,120,180,240,300].map(a=>`\u003cpath transform=\"rotate(${a} 16 16)\" d=\"M16 16c0-3 1.4-5 3.6-5.6-.4 2.4-1.6 4.3-3.6 5.6z\"/>`).join('')}\u003ccircle cx=\"16\" cy=\"16\" r=\"1.8\"/>\u003c/g>\u003c/svg>`;\n"},"/assets/js/ui/inspector.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// المفتش: لوحة خصائص العنصر المحدد في المشهد\n// يرسل التعديلات عبر onChange(key, value) ولا يكتب في الحالة مباشرة\n// ═══════════════════════════════════════════════════════════════\nimport { el } from '../core/dom.js';\nimport { n0, n1, n2 } from '../core/format.js';\nimport { LIMITS } from '../core/sanitize.js';\nimport { BUILDINGS } from '../data/buildings.js';\nimport { MATERIALS, DIAMETERS } from '../data/materials.js';\nimport { PUMP_TYPES, byId, SOURCES } from '../data/pumps.js';\nimport { demand } from '../engine/demand.js';\n\nconst get = (s, k) => k.split('.').reduce((o, p) => o && o[p], s);\n\nfunction rangeField(s, label, key, unit, onChange, maxOverride) {\n  const [a, b, st] = LIMITS[key], max = maxOverride ?? b, v = get(s, key);\n  const range = el('input', { type: 'range', min: a, max, step: st, value: v, id: 'r-' + key, 'aria-label': label });\n  const box = el('input', { class: 'input', type: 'number', inputmode: 'decimal', min: a, max, step: st, value: v, 'aria-label': label + ' (' + unit + ')' });\n  range.addEventListener('input', () => { box.value = range.value; onChange(key, Number(range.value)); });\n  box.addEventListener('change', () => { const n = Math.min(max, Math.max(a, Number(box.value) || a)); box.value = n; range.value = n; onChange(key, n); });\n  return el('div', { class: 'field' }, el('label', { for: 'r-' + key, text: label }),\n    el('div', { class: 'range-row' }, range, el('div', { class: 'unit-box' }, box, el('span', { text: unit }))));\n}\nfunction selectField(s, label, key, options, onChange) {\n  const v = String(get(s, key));\n  const sel = el('select', { class: 'input', id: 's-' + key },\n    ...options.map(([val, name]) => el('option', { value: val, selected: String(val) === v, text: name })));\n  sel.addEventListener('change', () => onChange(key, key.endsWith('.d') ? Number(sel.value) : sel.value));\n  return el('div', { class: 'field' }, el('label', { for: 's-' + key, text: label }), sel);\n}\nconst head = (kicker, title, sub) => el('div', { class: 'insp-head' }, el('div', { class: 'kicker', text: kicker }), el('h2', { text: title }), sub ? el('p', { text: sub }) : null);\nconst note = t => el('p', { class: 'note', text: t });\n\nfunction demandNote(s) {\n  const D = demand(s);\n  return note(`الطلب اليومي ${n1(D.daily)} م³ لـ ${n0(D.people)} شخص. الموصى به: خزان علوي ${n1(D.roofRec)} م³، أرضي ${n0(D.groundRec)} م³، وتدفق ${n2(D.qReq)} م³/س.`);\n}\n\nexport function readout(R) {\n  const cell = (k, v, u) => el('div', {}, el('small', { text: k }), el('b', { class: 'num', text: v }), u ? el('i', { text: u }) : null);\n  return el('div', { class: 'readout', id: 'readout' },\n    cell('التدفق', n2(R.q), 'م³/س'), cell('الضاغط', n1(R.h), 'م'),\n    cell('الكفاءة ≈', n0(R.eta * 100) + '%'), cell('ملء الخزان العلوي', R.flows ? n0(R.fillMin) : '—', 'دقيقة'));\n}\n\nconst STEPS = [['المبنى', s => !!s.building], ['الخزان العلوي', s => !!s.roof], ['الخزان الأرضي', s => !!s.ground], ['المضخة والمواسير', s => !!s.pump]];\n\nexport function renderInspector(root, s, ui, R, { onChange, onAction }) {\n  root.replaceChildren();\n  const sel = ui.selected, body = el('div', { class: 'insp-body' });\n\n  if (sel === 'building' && s.building) {\n    const B = s.building, T = BUILDINGS[B.type];\n    const seg = el('div', { class: 'seg', role: 'group', 'aria-label': 'نوع المبنى' },\n      ...Object.entries(BUILDINGS).map(([k, b]) => el('button', { 'aria-pressed': String(k === B.type), text: b.name, onclick: () => onAction('buildingType', k) })));\n    body.append(el('div', { class: 'field' }, el('span', { class: 'lab', text: 'النوع' }), seg),\n      rangeField(s, 'عدد الأدوار', 'building.floors', 'دور', onChange),\n      rangeField(s, 'ارتفاع الدور', 'building.floorH', 'م', onChange),\n      rangeField(s, T.people + ' في الدور', 'building.perFloor', 'شخص', onChange),\n      rangeField(s, 'المسافة بين الخزان الأرضي والمبنى', 'site', 'م', onChange),\n      demandNote(s));\n    root.append(head('المبنى', T.name, T.desc), body);\n  } else if (sel === 'ground' && s.ground) {\n    body.append(rangeField(s, 'السعة', 'ground.vol', 'م³', onChange), rangeField(s, 'عمق سطح الماء تحت الأرض', 'ground.depth', 'م', onChange), demandNote(s));\n    root.append(head('خزان', 'الخزان الأرضي', 'مصدر الماء للمضخة'), body);\n  } else if (sel === 'roof' && s.roof) {\n    body.append(rangeField(s, 'السعة', 'roof.vol', 'م³', onChange), demandNote(s));\n    root.append(head('خزان', 'الخزان العلوي', 'على السطح، يغذّي الأدوار بالجاذبية'), body);\n  } else if (sel === 'pump' && s.pump) {\n    const p = byId(s.pump.id), src = SOURCES[p.src];\n    body.append(\n      el('button', { class: 'btn', style: 'width:100%;margin-bottom:16px', text: 'غيّر المضخة', onclick: () => onAction('pickPump') }),\n      rangeField(s, 'بُعد المضخة عن الخزان الأرضي', 'pump.x', 'م', onChange, s.site - 0.5),\n      p.type === 'sub' ? note('المضخة الغاطسة في قاع الخزان الأرضي.') : rangeField(s, 'ارتفاع محور المضخة فوق الأرض', 'pump.z', 'م', onChange),\n      (() => { const c = el('input', { type: 'checkbox', checked: s.autoLength }); c.addEventListener('change', () => onAction('autoLength', c.checked));\n        return el('label', { class: 'check' }, c, el('span', { text: 'اضبط أطوال المواسير وصمام الخنق تلقائياً' })); })(),\n      el('p', { class: 'note' }, el('span', { text: `المصدر: ${src.title}. ` }), el('a', { href: 'catalog.html#' + p.id, text: 'عرض بيانات الكتالوج' })));\n    root.append(head(PUMP_TYPES[p.type].name + ' · ' + p.kw + ' ك.واط', p.model, `أقصى ضاغط ${n1(p.curve[0][1])} م · منافذ ${p.ports}`), body);\n  } else if ((sel === 'suction' || sel === 'discharge') && s[sel]) {\n    const k = sel;\n    body.append(rangeField(s, 'الطول', k + '.L', 'م', onChange),\n      selectField(s, 'القطر الداخلي', k + '.d', DIAMETERS.map(d => [d, d + ' مم']), onChange),\n      selectField(s, 'المادة', k + '.mat', Object.entries(MATERIALS).map(([m, o]) => [m, `${o.name} — خشونة ${o.e} مم، ${o.pn} بار`]), onChange),\n      rangeField(s, 'عدد الأكواع 90°', k + '.elbows', 'كوع', onChange),\n      k === 'discharge' ? rangeField(s, 'صمام الخنق (معامل K إضافي)', 'discharge.valveK', 'K', onChange) : null,\n      note(k === 'suction' ? 'يُحسب تلقائياً: صمام قدم بمصفاة (K=2.5) ومدخل (K=0.5). ذاتية التحضين بلا صمام قدم.' : 'يُحسب تلقائياً: صمام عدم رجوع (K=2.0) وبوابة (K=0.2) ومخرج (K=1.0).'));\n    root.append(head('ماسورة', k === 'suction' ? 'ماسورة السحب' : 'ماسورة الدفع', k === 'suction' ? 'من الخزان الأرضي إلى المضخة' : 'من المضخة إلى مدخل الخزان العلوي'), body);\n  } else if (sel === 'env') {\n    body.append(rangeField(s, 'حرارة الماء', 'env.waterTempC', '°م', onChange), rangeField(s, 'الارتفاع عن سطح البحر', 'env.altitudeM', 'م', onChange),\n      rangeField(s, 'ساعات الضخ اليومية', 'env.pumpingHours', 'س', onChange), rangeField(s, 'تعرفة الكهرباء', 'env.tariff', 'ريال', onChange),\n      note('الحرارة تغيّر الكثافة واللزوجة وضغط البخار، والارتفاع يغيّر الضغط الجوي؛ وكلاهما يؤثر على NPSH المتاح.'));\n    root.append(head('ظروف التشغيل', 'الموقع والماء', 'تُطبَّق على الحساب كله'), body);\n  } else {\n    const list = el('ol', { class: 'sequence' });\n    let marked = false;\n    for (const [name, done] of STEPS) { const d = done(s); const li = el('li', { text: name }); if (d) li.className = 'done'; else if (!marked) { li.className = 'now'; marked = true; } list.append(li); }\n    body.append(list);\n    if (R) body.append(readout(R), note('اضغط أي عنصر في اللوحة لتعديله: المبنى، الخزانين، المضخة، أو أي ماسورة.'));\n    else body.append(note('اضغط المربع المنقّط التالي في اللوحة لإضافته.'));\n    root.append(head('pump.zeen', R ? 'التصميم مكتمل' : 'خطوات التصميم', R ? 'شغّل لترى الماء، أو افتح المذكرة الحسابية.' : 'أربع خطوات، وكل خطوة قابلة للتعديل لاحقاً.'), body);\n  }\n}\n"},"/assets/js/ui/pickers.js":{"type":"text/javascript; charset=utf-8","text":"// نافذتا اختيار المبنى واختيار المضخة\nimport { el } from '../core/dom.js';\nimport { n1, n2 } from '../core/format.js';\nimport { openDialog, closeDialog } from './common.js';\nimport { BUILDINGS } from '../data/buildings.js';\nimport { PUMP_TYPES, ofType, SOURCES } from '../data/pumps.js';\nimport { trial, recommendPump } from '../engine/recommend.js';\nimport { sparkline } from './chart.js';\n\nconst ICONS = {\n  house: '\u003cpath d=\"M14 70V38L50 16l36 22v32z\" class=\"s-fill\"/>\u003crect x=\"42\" y=\"48\" width=\"16\" height=\"22\" class=\"s-win\"/>\u003crect x=\"22\" y=\"44\" width=\"12\" height=\"10\" class=\"s-win\"/>\u003crect x=\"66\" y=\"44\" width=\"12\" height=\"10\" class=\"s-win\"/>',\n  school: '\u003crect x=\"6\" y=\"26\" width=\"88\" height=\"44\" class=\"s-fill\"/>\u003crect x=\"4\" y=\"22\" width=\"92\" height=\"5\" class=\"s-slab\"/>' + [0, 1, 2, 3].map(i => `\u003crect x=\"${12 + i * 21}\" y=\"34\" width=\"12\" height=\"10\" class=\"s-win\"/>`).join('') + '\u003crect x=\"42\" y=\"52\" width=\"16\" height=\"18\" class=\"s-win\"/>\u003cpath d=\"M14 22V6h14v8H14\" class=\"s-thin\"/>',\n  factory: '\u003cpath d=\"M6 70V32l22-12v12l22-12v12l22-12v50z\" class=\"s-fill\"/>\u003crect x=\"80\" y=\"8\" width=\"10\" height=\"62\" class=\"s-fill\"/>\u003crect x=\"30\" y=\"50\" width=\"20\" height=\"20\" class=\"s-win\"/>',\n};\n\nexport function buildingPicker(onPick) {\n  const grid = el('div', { style: 'display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px' });\n  for (const [k, b] of Object.entries(BUILDINGS)) {\n    const card = el('button', { class: 'btn', style: 'flex-direction:column;align-items:stretch;text-align:start;padding:14px;height:auto;gap:8px', onclick: () => { closeDialog(); onPick(k); } });\n    card.innerHTML = `\u003csvg viewBox=\"0 0 100 74\" style=\"width:100%;height:84px\" aria-hidden=\"true\">${ICONS[k]}\u003cline x1=\"0\" x2=\"100\" y1=\"70\" y2=\"70\" class=\"s-ground\"/>\u003c/svg>`;\n    card.append(el('b', { text: b.name, style: 'font-size:17px' }), el('span', { class: 'muted small', text: b.desc }));\n    grid.append(card);\n  }\n  openDialog({ title: 'نوع المبنى', sub: 'يحدد الاستهلاك اليومي وارتفاع الدور الافتراضي. تقدر تغيّره لاحقاً.', body: grid });\n}\n\nexport function pumpPicker(state, current, onPick) {\n  let type = current ? current.type : 'surface';\n  const body = el('div');\n  const draw = () => {\n    const rec = recommendPump(state, type);\n    const tabs = el('div', { class: 'seg', role: 'tablist', style: 'margin-bottom:12px' },\n      ...Object.entries(PUMP_TYPES).map(([k, t]) => el('button', { role: 'tab', 'aria-pressed': String(k === type), text: t.name, onclick: () => { type = k; draw(); } })));\n    const rows = ofType(type).map(p => {\n      const R = trial(state, p.id);\n      const st = R.noLift ? ['bad', 'لا ترفع'] : R.air ? ['bad', 'السحب لا يصل'] : R.runout ? ['bad', 'بعد نهاية المنحنى'] : R.tempC > p.tMax ? ['bad', 'حرارة عالية']\n        : (!R.sub && (R.margin \u003c 0.5 || R.g.lift > p.maxLift)) ? ['bad', 'تكهف'] : R.q \u003c R.D.qReq ? ['warn', 'تدفق أقل'] : ['ok', 'مناسبة'];\n      const tr = el('tr', { class: (p.id === rec ? 'rec ' : '') + (current && current.id === p.id ? 'cur' : ''), tabindex: '0' },\n        el('td', {}, el('b', { text: p.model }), el('div', { class: 'muted small', text: p.kw + ' ك.واط · ' + p.ports })),\n        el('td', { class: 'opt' }), el('td', { class: 'n', text: n1(p.curve[0][1]) }), el('td', { class: 'n opt', text: n1(p.curve.at(-1)[0] * 0.06) }),\n        el('td', { class: 'n', text: R.noLift ? '—' : n2(R.q) }), el('td', {}, el('span', { class: 'tag ' + st[0], text: st[1] })));\n      tr.children[1].innerHTML = sparkline(p);\n      const pick = () => { closeDialog(); onPick(p.id); };\n      tr.addEventListener('click', pick); tr.addEventListener('keydown', e => { if (e.key === 'Enter') pick(); });\n      return tr;\n    });\n    const table = el('table', { class: 'table pump-table' },\n      el('thead', {}, el('tr', {}, ...['الموديل', 'المنحنى', 'أقصى ضاغط م', 'أقصى تدفق م³/س', 'التشغيل هنا م³/س', 'الحكم'].map((h, i) => el('th', { class: (i >= 2 && i \u003c= 4 ? 'n ' : '') + (i === 1 || i === 3 ? 'opt' : ''), text: h })))),\n      el('tbody', {}, ...rows));\n    const src = SOURCES[ofType(type)[0].src];\n    body.replaceChildren(tabs, el('p', { class: 'note', text: PUMP_TYPES[type].note }), el('div', { class: 'scroll-x' }, table),\n      el('p', { class: 'source-line' }, el('span', { text: 'المصدر: ' + src.title + ' — ' }), el('a', { href: src.url, target: '_blank', rel: 'noopener noreferrer', text: 'ملف الكتالوج' }), el('span', { text: ' · ' }), el('a', { href: 'catalog.html', target: '_blank', rel: 'noopener', text: 'كل الكتالوج' })));\n  };\n  draw();\n  openDialog({ title: 'اختيار المضخة', sub: 'التشغيل محسوب على تصميمك الحالي من منحنيات الكتالوج الحقيقية. «موصى بها» = أصغر مضخة تحقق الطلب قرب أفضل كفاءة وبلا تكهف.', body, wide: true });\n}\n"},"/assets/js/ui/saved.js":{"type":"text/javascript; charset=utf-8","text":"// نافذة «تصاميمي»: حفظ، فتح، حذف\nimport { el } from '../core/dom.js';\nimport { date } from '../core/format.js';\nimport { openDialog, closeDialog, toast, confirmButton } from './common.js';\nimport { designs } from '../storage/designs.js';\nimport { cleanDesign } from '../core/sanitize.js';\n\nexport function openSaved(getState, { currentId, onOpen, onSaved }) {\n  const s = getState();\n  const list = el('div', { style: 'display:grid;gap:0;margin-top:16px' }, el('p', { class: 'muted small', text: 'جارٍ التحميل…' }));\n  const nameIn = el('input', { class: 'input', id: 'dname', maxlength: 60, value: s.name || '', placeholder: 'مثال: فيلا حي الملقا' });\n  const saveBtn = el('button', { class: 'btn primary', text: currentId ? 'حفظ التعديلات' : 'حفظ التصميم' });\n  const saveAs = currentId ? el('button', { class: 'btn', text: 'حفظ كنسخة جديدة' }) : null;\n  const doSave = async asNew => {\n    saveBtn.disabled = true;\n    try { const st = getState(); st.name = nameIn.value; const id = await designs.save(nameIn.value, st, asNew ? null : currentId); onSaved(id); toast('حُفظ التصميم'); closeDialog(); }\n    catch (e) { toast(e.message || 'تعذّر الحفظ'); } finally { saveBtn.disabled = false; }\n  };\n  saveBtn.onclick = () => doSave(false); if (saveAs) saveAs.onclick = () => doSave(true);\n\n  const top = s.building ? el('div', {}, el('div', { class: 'field' }, el('label', { for: 'dname', text: 'اسم التصميم' }), nameIn), el('div', { style: 'display:flex;gap:8px;flex-wrap:wrap' }, saveBtn, saveAs)) : el('p', { class: 'note', text: 'ابدأ تصميماً ثم احفظه هنا.' });\n  openDialog({ title: 'تصاميمي', sub: 'محفوظة في حسابك ولا يراها غيرك.', body: el('div', {}, top, el('h3', { text: 'المحفوظة', style: 'font-size:15px;margin-top:22px;padding-bottom:8px;border-bottom:1.5px solid var(--ink)' }), list) });\n\n  const timer = setTimeout(() => list.replaceChildren(el('p', { class: 'muted small', text: 'تعذّر الوصول إلى التصاميم الآن.' })), 10000);\n  designs.list().then(items => {\n    clearTimeout(timer);\n    if (!items.length) { list.replaceChildren(el('p', { class: 'muted small', text: 'لا توجد تصاميم محفوظة بعد.' })); return; }\n    list.replaceChildren(...items.map(it => {\n      const del = el('button', { class: 'btn sm quiet danger', text: 'حذف' });\n      const row = el('div', { style: 'display:flex;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid var(--rule-soft)' },\n        el('div', { style: 'flex:1;min-width:0' }, el('div', { text: it.name, style: 'font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap' }), el('div', { class: 'muted small num', text: it.updated ? date(it.updated) : '' })),\n        el('button', { class: 'btn sm', text: 'فتح', onclick: async () => { try { const d = await designs.load(it.id); if (!d) throw 0; onOpen(cleanDesign(d), it.id); closeDialog(); toast('فُتح التصميم'); } catch { toast('تعذّر فتح التصميم'); } } }), del);\n      confirmButton(del, 'تأكيد الحذف', async () => { try { await designs.remove(it.id); row.remove(); } catch { toast('تعذّر الحذف'); } });\n      return row;\n    }));\n  }).catch(e => { clearTimeout(timer); list.replaceChildren(el('p', { class: 'muted small', text: e.message || 'تعذّر الوصول إلى التصاميم.' })); });\n}\n"},"/assets/js/ui/scene.js":{"type":"text/javascript; charset=utf-8","text":"// ═══════════════════════════════════════════════════════════════\n// المشهد: مقطع رأسي للموقع بأسلوب المخطط الهندسي\n// يرسم SVG فقط من الحالة ونتيجة الحساب؛ لا يغيّر شيئاً\n// النقر يمر عبر data-act ويُعالج في pages/app.js\n// ═══════════════════════════════════════════════════════════════\nimport { BUILDINGS } from '../data/buildings.js';\nimport { MATERIALS } from '../data/materials.js';\nimport { n1, n2 } from '../core/format.js';\nimport { esc } from '../core/dom.js';\n\nconst W = 1000, H = 560, GY = 360;           // خط الأرض\nconst TANK = { x0: 70, x1: 230, y0: GY, y1: 530 };\nconst BW = { house: 210, school: 270, factory: 280 };\n\nconst P = pts => 'M' + pts.map(p => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join('L');\nconst txt = (x, y, s, cls = '', anchor = 'middle', extra = '') => `\u003ctext class=\"s-txt ${cls}\" x=\"${x}\" y=\"${y}\" text-anchor=\"${anchor}\" ${extra}>${s}\u003c/text>`;\nconst num = s => `\u003ctspan class=\"s-num\">${s}\u003c/tspan>`;\n\nfunction defs() {\n  return `\u003cdefs>\n  \u003cpattern id=\"pEarth\" width=\"9\" height=\"9\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\">\u003cline x1=\"0\" y1=\"0\" x2=\"0\" y2=\"9\" class=\"s-hair\"/>\u003c/pattern>\n  \u003cpattern id=\"pConc\" width=\"16\" height=\"16\" patternUnits=\"userSpaceOnUse\">\u003ccircle cx=\"3\" cy=\"4\" r=\"1\" fill=\"var(--ink-3)\"/>\u003ccircle cx=\"11\" cy=\"11\" r=\".8\" fill=\"var(--ink-3)\"/>\u003cpath d=\"M10 3l2 3h-4z\" fill=\"none\" stroke=\"var(--ink-3)\" stroke-width=\".6\"/>\u003c/pattern>\n  \u003cpattern id=\"pGrid\" width=\"20\" height=\"20\" patternUnits=\"userSpaceOnUse\">\u003cpath d=\"M20 0H0V20\" fill=\"none\" stroke=\"var(--rule-soft)\" stroke-width=\".5\"/>\u003c/pattern>\n  \u003cmarker id=\"mArr\" viewBox=\"0 0 8 8\" refX=\"7\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\u003cpath d=\"M0 0L8 4L0 8z\" class=\"s-arrow\"/>\u003c/marker>\n  \u003c/defs>`;\n}\n\n// علامة منسوب ▽\n// الأرقام بأسلوب LTR صريح حتى لا يقلبها اتجاه الصفحة\nfunction level(x, y, label, toRight = true) {\n  const tx = toRight ? x + 10 : x - 10, a = toRight ? 'start' : 'end';\n  return `\u003cg>\u003cpath d=\"M${x - 6} ${y - 9}h12l-6 9z\" class=\"s-fill\" style=\"stroke-width:.9\"/>\u003cline x1=\"${x - 12}\" x2=\"${x + 12}\" y1=\"${y}\" y2=\"${y}\" class=\"s-thin\"/>${txt(tx, y - 12, label, 'mute', a, 'direction=\"ltr\"')}\u003c/g>`;\n}\n// بُعد رأسي\nfunction dimV(x, y1, y2, label) {\n  const m = (y1 + y2) / 2;\n  return `\u003cg>\u003cline x1=\"${x - 5}\" x2=\"${x + 5}\" y1=\"${y1}\" y2=\"${y1}\" class=\"s-dim\"/>\u003cline x1=\"${x - 5}\" x2=\"${x + 5}\" y1=\"${y2}\" y2=\"${y2}\" class=\"s-dim\"/>\n  \u003cline x1=\"${x}\" x2=\"${x}\" y1=\"${y1}\" y2=\"${y2}\" class=\"s-dim\" marker-start=\"url(#mArr)\" marker-end=\"url(#mArr)\"/>\n  \u003crect x=\"${x - 9}\" y=\"${m - 38}\" width=\"18\" height=\"76\" class=\"s-tagbg\"/>${txt(x, m, num(label), 'mute', 'middle', `transform=\"rotate(-90 ${x} ${m})\" dominant-baseline=\"middle\"`)}\u003c/g>`;\n}\nfunction slot(x, y, w, h, label, act, next) {\n  return `\u003cg class=\"slot${next ? ' next' : ''}\" data-act=\"${act}\" tabindex=\"0\" role=\"button\" aria-label=\"${label}\">\n  \u003crect x=\"${x}\" y=\"${y}\" width=\"${w}\" height=\"${h}\" rx=\"2\"/>\u003cpath class=\"plus\" d=\"M${x + w / 2 - 8} ${y + h / 2 - 12}h16M${x + w / 2} ${y + h / 2 - 20}v16\"/>\n  ${txt(x + w / 2, y + h / 2 + 18, label)}\u003c/g>`;\n}\n\nfunction building(s, sel) {\n  const B = s.building, w = BW[B.type], x0 = W - 90 - w, x1 = x0 + w;\n  const fpx = Math.min(48, 240 / B.floors), h = B.floors * fpx, top = GY - h;\n  const bays = B.type === 'house' ? 3 : B.type === 'school' ? 5 : 4;\n  let o = `\u003cg class=\"hot${sel === 'building' ? ' is-sel' : ''}\" data-act=\"building\" tabindex=\"0\" role=\"button\" aria-label=\"المبنى\">`;\n  o += `\u003crect x=\"${x0}\" y=\"${top}\" width=\"${w}\" height=\"${h}\" class=\"s-fill\"/>`;\n  for (let f = 0; f \u003c B.floors; f++) {\n    const yb = GY - f * fpx, yt = yb - fpx;\n    o += `\u003crect x=\"${x0 - 3}\" y=\"${yt}\" width=\"${w + 6}\" height=\"4\" class=\"s-slab\"/>`;\n    for (let c = 0; c \u003c bays; c++) {\n      const bw = w / bays, wx = x0 + c * bw + bw * 0.2, ww = bw * 0.6;\n      if (f === 0 && c === Math.floor(bays / 2)) { o += `\u003crect x=\"${wx + ww * 0.2}\" y=\"${yb - fpx * 0.72}\" width=\"${ww * 0.6}\" height=\"${fpx * 0.72}\" class=\"s-win\"/>`; continue; }\n      o += `\u003crect x=\"${wx}\" y=\"${yt + fpx * 0.3}\" width=\"${ww}\" height=\"${fpx * 0.42}\" class=\"s-win\"/>\u003cline x1=\"${wx + ww / 2}\" x2=\"${wx + ww / 2}\" y1=\"${yt + fpx * 0.3}\" y2=\"${yt + fpx * 0.72}\" class=\"s-hair\"/>`;\n    }\n  }\n  if (B.type === 'factory') { for (let i = 0; i \u003c 4; i++) o += `\u003cpath d=\"M${x0 + i * w / 4} ${top}l${w / 4} -22v22\" class=\"s-thin\"/>`; o += `\u003crect x=\"${x1 - 34}\" y=\"${top - 70}\" width=\"16\" height=\"70\" class=\"s-fill\"/>`; }\n  if (B.type === 'school') o += `\u003cline x1=\"${x0 + 18}\" x2=\"${x0 + 18}\" y1=\"${top}\" y2=\"${top - 46}\" class=\"s-thin\"/>\u003cpath d=\"M${x0 + 18} ${top - 46}h22v12h-22\" class=\"s-fill\"/>`;\n  o += `\u003crect x=\"${x0 - 3}\" y=\"${top - 10}\" width=\"${w + 6}\" height=\"10\" class=\"s-fill\"/>\u003c/g>`;\n  // مناسيب الأدوار\n  for (let f = 1; f \u003c= B.floors; f++) if (B.floors \u003c= 8 || f % 2 === 0 || f === B.floors) o += level(x1 + 14, GY - f * fpx, '+' + n2(f * B.floorH));\n  return { o, x0, x1, top };\n}\n\nfunction pipe(pts, frac, key, p, flowing, V, sel) {\n  const pts2 = cutPath(pts, frac), d = P(pts2), w = 3 + p.d / 14;\n  const mid = labelPoint(pts2);\n  const lab = `${key === 'suction' ? 'سحب' : 'دفع'} · ${esc(MATERIALS[p.mat].name)} Ø${p.d} · L ${n1(p.L)} م`;\n  const tw = lab.length * 6.3 + 18;\n  return { end: pts2[pts2.length - 1], svg: `\u003cg class=\"${sel === key ? 'is-sel' : ''}\">\n    \u003cpath d=\"${d}\" class=\"pipe-wall\" stroke-width=\"${w + 2.5}\"/>\u003cpath d=\"${d}\" class=\"pipe-core ${p.mat}\" stroke-width=\"${w}\"/>\n    ${flowing ? `\u003cpath d=\"${d}\" class=\"pipe-flow\" stroke-width=\"${Math.max(1.6, w - 3)}\" style=\"animation-duration:${Math.min(2, Math.max(.25, 1 / Math.max(V, .2))).toFixed(2)}s\"/>` : ''}\u003c/g>\n    \u003cpath d=\"${d}\" class=\"pipe-hit\" data-act=\"${key}\"/>\n    \u003cg class=\"hot\" data-act=\"${key}\" tabindex=\"0\" role=\"button\" aria-label=\"ماسورة ${key === 'suction' ? 'السحب' : 'الدفع'}\">\n      \u003cline x1=\"${mid[0]}\" y1=\"${mid[1]}\" x2=\"${mid[0]}\" y2=\"${mid[1] - 18}\" class=\"s-dim\"/>\n      \u003crect x=\"${mid[0] - tw / 2}\" y=\"${mid[1] - 40}\" width=\"${tw}\" height=\"22\" class=\"s-fill\" style=\"stroke-width:.8\"/>\n      ${txt(mid[0], mid[1] - 25, lab)}\u003c/g>` };\n}\nfunction cutPath(pts, fr) {\n  if (fr >= 1) return pts;\n  const seg = []; let tot = 0;\n  for (let i = 1; i \u003c pts.length; i++) { const l = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]); seg.push(l); tot += l; }\n  let want = tot * Math.max(0.05, fr); const out = [pts[0]];\n  for (let i = 1; i \u003c pts.length; i++) {\n    if (want \u003c= seg[i - 1]) { const k = want / seg[i - 1]; out.push([pts[i - 1][0] + (pts[i][0] - pts[i - 1][0]) * k, pts[i - 1][1] + (pts[i][1] - pts[i - 1][1]) * k]); return out; }\n    want -= seg[i - 1]; out.push(pts[i]);\n  }\n  return out;\n}\nfunction labelPoint(pts) { // منتصف أطول مقطع أفقي\n  let best = null, bl = -1;\n  for (let i = 1; i \u003c pts.length; i++) if (Math.abs(pts[i][1] - pts[i - 1][1]) \u003c 1) { const l = Math.abs(pts[i][0] - pts[i - 1][0]); if (l > bl) { bl = l; best = [(pts[i][0] + pts[i - 1][0]) / 2, pts[i][1]]; } }\n  return best || pts[Math.floor(pts.length / 2)];\n}\n\nexport function renderScene(s, ui, R) {\n  const sel = ui.selected, run = ui.running;\n  let o = defs() + `\u003crect width=\"${W}\" height=\"${H}\" fill=\"url(#pGrid)\"/>`;\n  // الأرض\n  o += `\u003crect x=\"0\" y=\"${GY}\" width=\"${W}\" height=\"${H - GY}\" fill=\"url(#pEarth)\"/>\u003cline x1=\"0\" x2=\"${W}\" y1=\"${GY}\" y2=\"${GY}\" class=\"s-ground\"/>`;\n  o += level(30, GY, '±0.00');\n\n  const next = !s.building ? 'addBuilding' : !s.roof ? 'addRoof' : !s.ground ? 'addGround' : !s.pump ? 'addPump' : null;\n  let Bd = null;\n  if (s.building) { Bd = building(s, sel); o += Bd.o; }\n  else o += slot(560, 120, 320, 200, 'أضف المبنى', 'addBuilding', true);\n\n  // الخزان الأرضي\n  let waterY = GY + 50;\n  if (s.ground) {\n    const { x0, x1, y1 } = TANK; waterY = GY + 14 + (s.ground.depth / 4.5) * (y1 - GY - 28);\n    o += `\u003cg class=\"hot${sel === 'ground' ? ' is-sel' : ''}\" data-act=\"ground\" tabindex=\"0\" role=\"button\" aria-label=\"الخزان الأرضي\">\n      \u003crect x=\"${x0 - 12}\" y=\"${GY - 12}\" width=\"${x1 - x0 + 24}\" height=\"${y1 - GY + 24}\" fill=\"url(#pConc)\" class=\"s-fill\"/>\n      \u003crect x=\"${x0}\" y=\"${GY}\" width=\"${x1 - x0}\" height=\"${y1 - GY}\" class=\"s-fill\"/>\n      \u003crect x=\"${x0 + 1}\" y=\"${waterY}\" width=\"${x1 - x0 - 2}\" height=\"${y1 - waterY - 1}\" class=\"s-water\"/>\n      \u003cline x1=\"${x0}\" x2=\"${x1}\" y1=\"${waterY}\" y2=\"${waterY}\" class=\"s-wline\"/>\n      \u003crect x=\"${x0 + 18}\" y=\"${GY - 18}\" width=\"44\" height=\"6\" class=\"s-fill\"/>\n      ${txt((x0 + x1) / 2, y1 + 26, 'خزان أرضي ' + num(n1(s.ground.vol)) + ' م³')}\u003c/g>`;\n    o += level(x1 + 30, waterY, '−' + n2(s.ground.depth));\n  } else if (s.building) o += slot(TANK.x0, GY + 30, TANK.x1 - TANK.x0, 130, 'الخزان الأرضي', 'addGround', next === 'addGround');\n\n  // الخزان العلوي\n  let rt = null;\n  if (s.building) {\n    const cx = Bd.x0 + (Bd.x1 - Bd.x0) * 0.62, tw = 96, th = 50, ty = Bd.top - 10 - 18 - th;\n    rt = { cx, top: ty, bottom: ty + th };\n    if (s.roof) {\n      const lv = th * Math.min(1, Math.max(0, ui.fill));\n      o += `\u003cg class=\"hot${sel === 'roof' ? ' is-sel' : ''}\" data-act=\"roof\" tabindex=\"0\" role=\"button\" aria-label=\"الخزان العلوي\">\n        \u003cpath d=\"M${cx - tw / 2 + 10} ${ty + th}v18M${cx + tw / 2 - 10} ${ty + th}v18M${cx - tw / 2 + 10} ${ty + th + 18}L${cx + tw / 2 - 10} ${ty + th}\" class=\"s-thin\"/>\n        \u003crect x=\"${cx - tw / 2}\" y=\"${ty}\" width=\"${tw}\" height=\"${th}\" class=\"s-fill\"/>\n        \u003crect id=\"roofWater\" x=\"${cx - tw / 2 + 1}\" y=\"${ty + th - lv}\" width=\"${tw - 2}\" height=\"${lv}\" class=\"s-water\"/>\n        ${txt(cx - tw / 2 - 10, ty + th / 2 + 4, 'خزان علوي ' + num(n1(s.roof.vol)) + ' م³', '', 'start')}\u003c/g>`;\n    } else o += slot(cx - 70, ty - 20, 140, th + 34, 'الخزان العلوي', 'addRoof', next === 'addRoof');\n  }\n\n  if (s.building && s.roof && s.ground && !s.pump) {\n    o += `\u003cpath d=\"M${TANK.x1 + 12} ${GY - 22}H${Bd.x0 - 26}V${rt.top - 22}H${rt.cx}\" fill=\"none\" stroke=\"var(--ink-3)\" stroke-width=\"1.2\" stroke-dasharray=\"3 5\"/>`;\n    o += slot((TANK.x1 + Bd.x0) / 2 - 85, GY - 150, 170, 100, 'أضف المضخة', 'addPump', true);\n    o += txt((TANK.x1 + Bd.x0) / 2, GY - 30, 'غير موصول — المضخة مطلوبة', 'mute');\n  }\n\n  if (R && s.pump) {\n    const sub = R.sub, px = TANK.x1 + (s.pump.x / s.site) * (Bd.x0 - TANK.x1 - 70) + 14;\n    const py = sub ? TANK.y1 - 34 : GY - 14 - s.pump.z * 26, rx = Bd.x0 - 26;\n    const go = run && !R.air && !R.noLift;\n    // الدفع\n    const dPts = sub ? [[150, py - 18], [150, GY - 34], [rx, GY - 34], [rx, rt.top - 22], [rt.cx, rt.top - 22], [rt.cx, rt.top + 4]]\n                     : [[px + 18, py - 14], [px + 18, py - 40], [rx, py - 40], [rx, rt.top - 22], [rt.cx, rt.top - 22], [rt.cx, rt.top + 4]];\n    const dp = pipe(dPts, Math.min(1, s.discharge.L / R.g.dischargeReq), 'discharge', s.discharge, go, R.L.d.V, sel);\n    o += dp.svg;\n    // السحب\n    if (!sub) {\n      const sPts = [[px - 26, py], [160, py], [160, waterY + 34]];\n      const sp = pipe(sPts, Math.min(1, s.suction.L / R.g.suctionReq), 'suction', s.suction, go, R.L.s.V, sel);\n      o += sp.svg;\n      if (!R.air) o += `\u003crect x=\"149\" y=\"${waterY + 32}\" width=\"22\" height=\"10\" class=\"s-fill\"/>\u003cpath d=\"M151 ${waterY + 36}h18M151 ${waterY + 39}h18\" class=\"s-hair\"/>`;\n      if (run && R.air) for (let i = 0; i \u003c 5; i++) o += `\u003ccircle class=\"fx-bub\" cx=\"${sp.end[0] + (i % 2 ? 4 : -4)}\" cy=\"${sp.end[1] - i * 7}\" r=\"${2.5 + i % 2}\" style=\"animation-delay:${i * .2}s\"/>`;\n      // بُعد السحب\n      o += dimV(px - 52, waterY, py, 'سحب ' + n2(R.g.lift) + ' م');\n    }\n    // جسم المضخة\n    const shake = run && (R.cavitation || R.air) ? ' fx-shake' : '';\n    if (sub) {\n      o += `\u003cg class=\"hot${sel === 'pump' ? ' is-sel' : ''}${shake}\" data-act=\"pump\" tabindex=\"0\" role=\"button\" aria-label=\"المضخة\">\n        \u003crect x=\"139\" y=\"${py - 18}\" width=\"22\" height=\"52\" rx=\"3\" class=\"s-fill\"/>\u003cpath d=\"M139 ${py + 6}h22M139 ${py + 10}h22\" class=\"s-hair\"/>\u003cpath d=\"M141 ${py + 16}h18\" class=\"s-thin\" stroke-dasharray=\"2 2\"/>\u003c/g>`;\n    } else {\n      o += `\u003cg class=\"hot${sel === 'pump' ? ' is-sel' : ''}${shake}\" data-act=\"pump\" tabindex=\"0\" role=\"button\" aria-label=\"المضخة\">\n        \u003crect x=\"${px - 40}\" y=\"${py + 12}\" width=\"78\" height=\"${GY - py - 12}\" fill=\"url(#pConc)\" class=\"s-fill\"/>\n        \u003crect x=\"${px - 36}\" y=\"${py - 14}\" width=\"40\" height=\"26\" class=\"s-fill\"/>\n        ${[0, 1, 2, 3, 4].map(i => `\u003cline x1=\"${px - 32 + i * 7}\" x2=\"${px - 32 + i * 7}\" y1=\"${py - 12}\" y2=\"${py + 10}\" class=\"s-hair\"/>`).join('')}\n        \u003ccircle cx=\"${px + 18}\" cy=\"${py - 1}\" r=\"15\" class=\"s-fill\"/>\n        \u003cg class=\"${run && R.q > 0 ? 'fx-spin' : ''}\">\u003ccircle cx=\"${px + 18}\" cy=\"${py - 1}\" r=\"6\" class=\"s-fill\"/>${[0, 60, 120].map(a => `\u003cline x1=\"${px + 12}\" x2=\"${px + 24}\" y1=\"${py - 1}\" y2=\"${py - 1}\" class=\"s-thin\" transform=\"rotate(${a} ${px + 18} ${py - 1})\"/>`).join('')}\u003c/g>\u003c/g>`;\n      if (run && R.cavitation && !R.air) for (let i = 0; i \u003c 6; i++) o += `\u003ccircle class=\"fx-bub\" cx=\"${px + 6 + i * 3}\" cy=\"${py + 4}\" r=\"${1.6 + i % 2}\" style=\"animation-delay:${i * .17}s\"/>`;\n    }\n    o += sub ? txt(132, py + 10, esc(R.pump.model), 'big', 'start') : txt(px, GY + 22, esc(R.pump.model), 'big');\n    // تسرب\n    if (run && R.leak) {\n      const e = dp.end;\n      for (let i = 0; i \u003c 4; i++) o += `\u003cellipse class=\"fx-drop\" cx=\"${e[0] + (i - 1.5) * 4}\" cy=\"${e[1] + 6}\" rx=\"2.5\" ry=\"4\" style=\"animation-delay:${i * .25}s\"/>`;\n      o += `\u003cellipse cx=\"${e[0]}\" cy=\"${GY + 5}\" rx=\"44\" ry=\"5\" class=\"s-water\"/>`;\n    }\n    // بُعد الرفع الساكن\n    o += dimV(W - 14, waterY, rt.top - 22, 'Hs ' + n2(R.g.Hs) + ' م');\n  }\n  return o;\n}\n\nexport const sceneSize = { W, H };\n"},"/catalog.html":{"type":"text/html; charset=utf-8","text":"\u003c!DOCTYPE html>\n\u003chtml lang=\"ar\" dir=\"rtl\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\u003cmeta name=\"referrer\" content=\"no-referrer\">\n\u003ctitle>كتالوج المضخات ومصادره — pump.zeen\u003c/title>\n\u003clink rel=\"icon\" href=\"assets/img/favicon.svg\" type=\"image/svg+xml\">\n\u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n\u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n\u003clink rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/tokens.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/base.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/app.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/report.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/pages.css\">\n\u003c/head>\n\u003cbody>\n\u003cheader class=\"topbar\">\n  \u003ca class=\"brand\" href=\"index.html\" aria-label=\"pump.zeen\">\u003cspan data-logo>\u003c/span>pump.zeen\u003c/a>\n  \u003cspan class=\"project\">كتالوج المضخات\u003c/span>\n  \u003ca class=\"btn quiet\" href=\"app.html\">المصمم\u003c/a>\n\u003c/header>\n\u003cmain class=\"page\">\n  \u003ch1>كتالوج المضخات ومصادره\u003c/h1>\n  \u003cp class=\"lead\">كل منحنى في المصمم منقول حرفياً من جدول الأداء في كتالوج الشركة المصنّعة. هنا الأرقام نفسها مع رابط الملف الأصلي لتتحقق منها بنفسك.\u003c/p>\n  \u003cdiv class=\"callout\">\n    \u003cb>ما المنقول وما المقدَّر\u003c/b>\n    \u003cp>المنقول من الكتالوج: نقاط الضاغط عند كل تدفق، قدرة المحرك P2، أقصى سحب، أقصى ضغط للجسم، حدود الحرارة، مقاسات المنافذ.\n    المقدَّر في الحساب: الكفاءة وNPSHr ونقطة أفضل كفاءة، لأن هذه الجداول لا تنشرها لهذه الموديلات الصغيرة. التقدير موضّح في المذكرة الحسابية، وراجع منحنيات المورد قبل الشراء.\u003c/p>\n  \u003c/div>\n  \u003cnav class=\"toc scroll-x\" id=\"toc\" aria-label=\"الأقسام\">\u003c/nav>\n  \u003cdiv id=\"list\">\u003c/div>\n\u003c/main>\n\u003cscript type=\"module\" src=\"assets/js/pages/catalog.js\">\u003c/script>\n\u003c/body>\n\u003c/html>\n"},"/index.html":{"type":"text/html; charset=utf-8","text":"\u003c!DOCTYPE html>\n\u003chtml lang=\"ar\" dir=\"rtl\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\u003cmeta name=\"referrer\" content=\"no-referrer\">\n\u003cmeta name=\"description\" content=\"pump.zeen — صمّم شبكة ضخ المياه لمبناك واحسبها بمنحنيات مضخات حقيقية.\">\n\u003ctitle>pump.zeen — تصميم شبكات ضخ المياه\u003c/title>\n\u003clink rel=\"icon\" href=\"assets/img/favicon.svg\" type=\"image/svg+xml\">\n\u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n\u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n\u003clink rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/tokens.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/base.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/scene.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/auth.css\">\n\u003c/head>\n\u003cbody>\n\u003cmain class=\"auth\">\n  \u003csection class=\"auth-art\">\n    \u003ca class=\"brand\" href=\"index.html\" aria-label=\"pump.zeen\">\u003cspan data-logo>\u003c/span>pump.zeen\u003c/a>\n    \u003ch1>صمّم شبكة الضخ لمبناك، واعرف قبل الشراء هل تعمل.\u003c/h1>\n    \u003cp class=\"lead\">ارسم الخزانين والمضخة والمواسير، ويحسب الموقع نقطة التشغيل والتكهف والطرق المائي من منحنيات مضخات حقيقية من كتالوج الشركة المصنّعة.\u003c/p>\n    \u003cdiv class=\"facts\">\n      \u003cdiv>\u003cb>منحنيات حقيقية\u003c/b>Pedrollo CP · JSW · 4SR بتردد 60 Hz\u003c/div>\n      \u003cdiv>\u003cb>مذكرة حسابية\u003c/b>Darcy–Weisbach، NPSH، جوكوفسكي\u003c/div>\n      \u003cdiv>\u003cb>إصلاح بضغطة\u003c/b>لكل مشكلة اقتراح قابل للتطبيق\u003c/div>\n    \u003c/div>\n    \u003cdiv class=\"frame\">\u003csvg id=\"hero\" viewBox=\"0 0 1000 560\" role=\"img\" aria-label=\"مثال: مقطع لشبكة ضخ لبيت من دورين\">\u003c/svg>\u003c/div>\n    \u003ca class=\"small muted\" href=\"catalog.html\">تصفّح كتالوج المضخات ومصادره ←\u003c/a>\n  \u003c/section>\n\n  \u003csection class=\"auth-side\">\n    \u003cdiv class=\"auth-card\">\n      \u003cdiv class=\"tabs\" role=\"tablist\">\n        \u003cbutton role=\"tab\" aria-selected=\"true\" data-tab=\"in\">تسجيل الدخول\u003c/button>\n        \u003cbutton role=\"tab\" aria-selected=\"false\" data-tab=\"up\">حساب جديد\u003c/button>\n      \u003c/div>\n\n      \u003cform id=\"fIn\" novalidate>\n        \u003cdiv class=\"field\">\u003clabel for=\"inEmail\">البريد الإلكتروني\u003c/label>\u003cinput class=\"input\" id=\"inEmail\" type=\"email\" autocomplete=\"username\" required dir=\"ltr\">\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"inPass\">كلمة المرور\u003c/label>\u003cinput class=\"input\" id=\"inPass\" type=\"password\" autocomplete=\"current-password\" required dir=\"ltr\">\u003c/div>\n        \u003cbutton class=\"btn primary wide\" type=\"submit\">دخول\u003c/button>\n        \u003cp style=\"margin-top:12px\">\u003cbutton class=\"linklike\" type=\"button\" id=\"forgot\">نسيت كلمة المرور؟\u003c/button>\u003c/p>\n      \u003c/form>\n\n      \u003cform id=\"fUp\" class=\"hidden\" novalidate>\n        \u003cdiv class=\"field\">\u003clabel for=\"upName\">الاسم\u003c/label>\u003cinput class=\"input\" id=\"upName\" maxlength=\"60\" autocomplete=\"name\" required>\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"upEmail\">البريد الإلكتروني\u003c/label>\u003cinput class=\"input\" id=\"upEmail\" type=\"email\" autocomplete=\"email\" required dir=\"ltr\">\u003c/div>\n        \u003cdiv class=\"field\">\u003clabel for=\"upPass\">كلمة المرور\u003c/label>\u003cinput class=\"input\" id=\"upPass\" type=\"password\" autocomplete=\"new-password\" minlength=\"10\" required dir=\"ltr\">\u003cdiv class=\"meter\">\u003ci id=\"meter\">\u003c/i>\u003c/div>\u003cspan class=\"small muted\">10 أحرف على الأقل، تشمل حروفاً وأرقاماً.\u003c/span>\u003c/div>\n        \u003cbutton class=\"btn primary wide\" type=\"submit\">إنشاء الحساب\u003c/button>\n      \u003c/form>\n\n      \u003cp class=\"msg\" id=\"msg\" role=\"status\">\u003c/p>\n      \u003cdiv class=\"secure\">\u003csvg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\">\u003cpath d=\"M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z\"/>\u003c/svg>\u003cspan>اتصال مشفّر، وكل مستخدم لا يرى إلا تصاميمه. الجلسة تُغلق تلقائياً بعد عدم النشاط.\u003c/span>\u003c/div>\n    \u003c/div>\n  \u003c/section>\n\u003c/main>\n\u003cscript type=\"module\" src=\"assets/js/pages/login.js\">\u003c/script>\n\u003c/body>\n\u003c/html>\n"},"/reset.html":{"type":"text/html; charset=utf-8","text":"\u003c!DOCTYPE html>\n\u003chtml lang=\"ar\" dir=\"rtl\">\n\u003chead>\n\u003cmeta charset=\"utf-8\">\n\u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\u003cmeta name=\"referrer\" content=\"no-referrer\">\n\u003cmeta name=\"robots\" content=\"noindex\">\n\u003ctitle>كلمة مرور جديدة — pump.zeen\u003c/title>\n\u003clink rel=\"icon\" href=\"assets/img/favicon.svg\" type=\"image/svg+xml\">\n\u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n\u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n\u003clink rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+Arabic:wght@400;500;600;700&display=swap\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/tokens.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/base.css\">\n\u003clink rel=\"stylesheet\" href=\"assets/css/auth.css\">\n\u003c/head>\n\u003cbody>\n\u003cmain class=\"auth\" style=\"grid-template-columns:1fr\">\n  \u003csection class=\"auth-side\">\n    \u003cform class=\"auth-card\" id=\"f\" novalidate>\n      \u003ca class=\"brand\" href=\"index.html\" aria-label=\"pump.zeen\">\u003cspan data-logo>\u003c/span>pump.zeen\u003c/a>\n      \u003ch1>كلمة مرور جديدة\u003c/h1>\n      \u003cp class=\"muted\">10 أحرف على الأقل، تشمل حروفاً وأرقاماً.\u003c/p>\n      \u003cdiv class=\"field\">\u003clabel for=\"p1\">كلمة المرور الجديدة\u003c/label>\u003cinput class=\"input\" id=\"p1\" type=\"password\" autocomplete=\"new-password\" dir=\"ltr\" required>\u003c/div>\n      \u003cdiv class=\"field\">\u003clabel for=\"p2\">أعد كتابتها\u003c/label>\u003cinput class=\"input\" id=\"p2\" type=\"password\" autocomplete=\"new-password\" dir=\"ltr\" required>\u003c/div>\n      \u003cbutton class=\"btn primary wide\" type=\"submit\">حفظ\u003c/button>\n      \u003cp class=\"msg\" id=\"msg\" role=\"status\">\u003c/p>\n    \u003c/form>\n  \u003c/section>\n\u003c/main>\n\u003cscript type=\"module\" src=\"assets/js/pages/reset.js\">\u003c/script>\n\u003c/body>\n\u003c/html>\n"},"/robots.txt":{"type":"text/plain; charset=utf-8","text":"User-agent: *\nAllow: /$\nAllow: /index.html\nAllow: /catalog\nDisallow: /app\nDisallow: /admin\nDisallow: /reset\n"}};
const RULES = [{"pattern":"/*","headers":{"Content-Security-Policy":"default-src 'self'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; style-src-attr 'unsafe-inline'; font-src https://fonts.gstatic.com; img-src 'self' data:; connect-src 'self' https://rmuwprafvgqwemohrcce.supabase.co; frame-ancestors 'none'; base-uri 'none'; form-action 'self'; object-src 'none'; upgrade-insecure-requests","Strict-Transport-Security":"max-age=63072000; includeSubDomains; preload","X-Content-Type-Options":"nosniff","X-Frame-Options":"DENY","Referrer-Policy":"no-referrer","Permissions-Policy":"camera=(), microphone=(), geolocation=(), payment=(), usb=(), interest-cohort=()","Cross-Origin-Opener-Policy":"same-origin","Cross-Origin-Resource-Policy":"same-origin"}},{"pattern":"/admin*","headers":{"Cache-Control":"no-store","X-Robots-Tag":"noindex, nofollow"}},{"pattern":"/app*","headers":{"Cache-Control":"no-store"}},{"pattern":"/assets/*","headers":{"Cache-Control":"public, max-age=3600"}}];
const CANONICAL = 'zeenpumps.com';
const esc = s => s.replace(/[.+?^${}()|[\]\\]/g, '\\$&');
const match = (pat, path) => new RegExp('^' + esc(pat).replace(/\*/g, '.*') + '$').test(path);
const bytes = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));

export default {
  async fetch(req) {
    const url = new URL(req.url);
    if (url.hostname === 'www.' + CANONICAL) { url.hostname = CANONICAL; return Response.redirect(url.toString(), 301); }
    if (req.method !== 'GET' && req.method !== 'HEAD') return new Response('Method Not Allowed', { status: 405, headers: { Allow: 'GET, HEAD' } });
    let path;
    try { path = decodeURIComponent(url.pathname); } catch { return new Response('Bad Request', { status: 400 }); }
    if (path.endsWith('/')) path += 'index.html';
    if (!FILES[path] && FILES[path + '.html']) path += '.html';
    const f = FILES[path];
    const headers = new Headers();
    for (const r of RULES) if (match(r.pattern, path) || match(r.pattern, url.pathname)) for (const [k, v] of Object.entries(r.headers)) headers.set(k, v);
    if (!f) {
      headers.set('Content-Type', 'text/html; charset=utf-8');
      return new Response('<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>404</title><p>الصفحة غير موجودة — <a href="/">الرئيسية</a></p></html>', { status: 404, headers });
    }
    headers.set('Content-Type', f.type);
    return new Response(req.method === 'HEAD' ? null : (f.b64 ? bytes(f.b64) : f.text), { headers });
  },
};
